class Solution:

    def minMovesToCaptureTheQueen(self, a, b, c, d, e, f):
        if a == e:
            return 2 if c == a and (b < d < f or b > d > f) else 1
        if b == f:
            return 2 if d == f and (a < c < e or a > c > e) else 1
        if c + d == e + f:
            return 2 if a + b == c + d and (c < a < e or c > a > e) else 1
        if c - d == e - f:
            return 2 if a - b == c - d and (c < a < e or c > a > e) else 1
        return 2

class Solution:

    def maxPartitionsAfterOperations(self, s, k):

        @functools.lru_cache(None)
        def dp(i, canChange, mask):
            """
      Returns the maximum number of partitions of s[i..n), where `canChange` is
      True if we can still change a letter, and `mask` is the bitmask of the
      letters we've seen.
      """
            if i == len(s):
                return 0

            def getRes(newBit, nextCanChange):
                newMask = mask | newBit
                if newMask.bit_count() > k:
                    return 1 + dp(i + 1, nextCanChange, newBit)
                return dp(i + 1, nextCanChange, newMask)
            res = getRes(1 << ord(s[i]) - ord('a'), canChange)
            if canChange:
                for j in range(26):
                    res = max(res, getRes(1 << j, False))
            return res
        return dp(0, True, 0) + 1

class Solution:

    def maximumSubtreeSize(self, edges, colors):
        ans = 1
        tree = [[] for _ in range(len(colors))]
        for u, v in edges:
            tree[u].append(v)

        def dfs(u):
            """
      Returns the size of subtree of u if every node in the subtree has the same
      color. Otherwise, returns -1.
      """
            nonlocal ans
            res = 1
            for v in tree[u]:
                if colors[v] != colors[u]:
                    res = -1
                subtreeSize = dfs(v)
                if subtreeSize == -1:
                    res = -1
                elif res != -1:
                    res += subtreeSize
            ans = max(ans, res)
            return res
        dfs(0)
        return ans

