class Solution:

    def findMaximumNumber(self, k, x):

        def getSumPrices(num):
            """Returns the sum of prices of all numbers from 1 to `num`."""
            sumPrices = 0
            num += 1
            for i in range(num.bit_length(), 0, -1):
                if i % x == 0:
                    groupSize = 1 << i
                    halfGroupSize = 1 << i - 1
                    sumPrices += num // groupSize * halfGroupSize
                    sumPrices += max(0, num % groupSize - halfGroupSize)
            return sumPrices
        l = 1
        r = 10 ** 15
        return bisect_right(range(l, r + 1), k, key=getSumPrices) - 1 + l

