class Solution:

    def minOrAfterOperations(self, nums, k):
        MAX_BIT = 30
        ans = 0
        prefixMask = 0
        for i in range(MAX_BIT, -1, -1):
            prefixMask |= 1 << i
            if self._getMergeOps(nums, prefixMask, ans) > k:
                ans |= 1 << i
        return ans

    def _getMergeOps(self, nums, prefixMask, target):
        """
    Returns the number of merge operations to turn `prefixMask` to the target
    by ANDing `nums`.
    """
        mergeOps = 0
        ands = prefixMask
        for num in nums:
            ands &= num
            if ands | target == target:
                ands = prefixMask
            else:
                mergeOps += 1
        return mergeOps

