class Solution:

    def minimumTimeToInitialState(self, word, k):
        n = len(word)
        maxOps = (n - 1) // k + 1
        z = self._zFunction(word)
        for ans in range(1, maxOps):
            if z[ans * k] >= n - ans * k:
                return ans
        return maxOps

    def _zFunction(self, s):
        """
    Returns the z array, where z[i] is the length of the longest prefix of
    s[i..n) which is also a prefix of s.

    https://cp-algorithms.com/string/z-function.html#implementation
    """
        n = len(s)
        z = [0] * n
        l = 0
        r = 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r - i, z[i - l])
            while i + z[i] < n and s[z[i]] == s[i + z[i]]:
                z[i] += 1
            if i + z[i] > r:
                l = i
                r = i + z[i]
        return z

class Solution:

    def resultGrid(self, image, threshold):
        m = len(image)
        n = len(image[0])
        sums = [[0] * n for _ in range(m)]
        counts = [[0] * n for _ in range(m)]
        for i in range(m - 2):
            for j in range(n - 2):
                if self._isRegion(image, i, j, threshold):
                    subgridSum = sum((image[x][y] for x in range(i, i + 3) for y in range(j, j + 3)))
                    for x in range(i, i + 3):
                        for y in range(j, j + 3):
                            sums[x][y] += subgridSum // 9
                            counts[x][y] += 1
        for i in range(m):
            for j in range(n):
                if counts[i][j] > 0:
                    image[i][j] = sums[i][j] // counts[i][j]
        return image

    def _isRegion(self, image, i, j, threshold):
        """Returns True if image[i..i + 2][j..j + 2] is a region."""
        for x in range(i, i + 3):
            for y in range(j, j + 3):
                if x > i and abs(image[x][y] - image[x - 1][y]) > threshold:
                    return bool(False)
                if y > j and abs(image[x][y] - image[x][y - 1]) > threshold:
                    return bool(False)
        return bool(True)

