class Solution:

    def maxOperations(self, nums):

        @functools.lru_cache(None)
        def dp(i, j, score):
            """
      Returns the maximum number of operations that can be performed for
      nums[i..j], s.t. all operations have the same `score`.
      """
            if i >= j:
                return 0
            deleteFirstTwo = 1 + dp(i + 2, j, score) if nums[i] + nums[i + 1] == score else 0
            deleteLastTwo = 1 + dp(i, j - 2, score) if nums[j] + nums[j - 1] == score else 0
            deleteFirstAndLast = 1 + dp(i + 1, j - 1, score) if nums[i] + nums[j] == score else 0
            return max(deleteFirstTwo, deleteLastTwo, deleteFirstAndLast)
        n = len(nums)
        return max(dp(0, n - 1, nums[0] + nums[1]), dp(0, n - 1, nums[-1] + nums[-2]), dp(0, n - 1, nums[0] + nums[-1]))

class TrieNode:

    def __init__(self):
        self.children = {}
        self.count = 0

class Trie:

    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        count = 0
        for i, prefix in enumerate(word):
            suffix = word[-1 - i]
            node = node.children.setdefault((prefix, suffix), TrieNode())
            count += node.count
        node.count += 1
        return count

