class Trie:

    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for c in word:
            node = node.children.setdefault(c, TrieNode())
        node.isWord = True

    def search(self, word):
        prefixLength = 0
        node = self.root
        for c in word:
            if c not in node.children:
                break
            node = node.children[c]
            prefixLength += 1
        return prefixLength

