class FenwickTree:

    def __init__(self, n):
        self.sums = [0] * (n + 1)

    def add(self, i, delta):
        while i < len(self.sums):
            self.sums[i] += delta
            i += FenwickTree.lowbit(i)

    def get(self, i):
        summ = 0
        while i > 0:
            summ += self.sums[i]
            i -= FenwickTree.lowbit(i)
        return summ

    @staticmethod
    def lowbit(i):
        return i & -i

class Solution:

    def getPermutationIndex(self, perm):
        MOD = 1000000007
        n = len(perm)
        ans = 0
        tree = FenwickTree(n)
        fact = [1] * (n + 1)
        for i in range(2, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        for i, num in enumerate(perm):
            unusedNums = num - 1 - tree.get(num - 1)
            suffixLength = fact[n - 1 - i]
            ans += unusedNums * suffixLength
            ans %= MOD
            tree.add(num, 1)
        return ans

