class Solution:

    def minRectanglesToCoverPoints(self, points, w):
        ans = 0
        prevX = -w - 1
        xs = sorted([x for x, _ in points])
        for x in xs:
            if x > prevX + w:
                ans += 1
                prevX = x
        return ans

class Solution:

    def minimumTime(self, n, edges, disappear):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        return self._dijkstra(graph, 0, disappear)

    def _dijkstra(self, graph, src, disappear):
        dist = [math.inf] * len(graph)
        dist[src] = 0
        minHeap = [(dist[src], src)]
        while minHeap:
            d, u = heapq.heappop(minHeap)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if d + w < disappear[v] and d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(minHeap, (dist[v], v))
        return [d if d != math.inf else -1 for d in dist]

class Solution:

    def findLatestTime(self, s):
        ans = list(s)
        if s[0] == '?':
            ans[0] = '1' if s[1] == '?' or s[1] < '2' else '0'
        if s[1] == '?':
            ans[1] = '1' if ans[0] == '1' else '9'
        if s[3] == '?':
            ans[3] = '5'
        if s[4] == '?':
            ans[4] = '9'
        return ''.join(ans)

class Solution:

    def maximumPrimeDifference(self, nums):
        MAX = 100
        isPrime = self._sieveEratosthenes(MAX + 1)
        minPrimeIndex = -1
        maxPrimeIndex = -1
        for i, num in enumerate(nums):
            if isPrime[num]:
                if minPrimeIndex == -1:
                    minPrimeIndex = i
                maxPrimeIndex = i
        return maxPrimeIndex - minPrimeIndex

    def _sieveEratosthenes(self, n):
        isPrime = [True] * n
        isPrime[0] = False
        isPrime[1] = False
        for i in range(2, int(n ** 0.5) + 1):
            if isPrime[i]:
                for j in range(i * i, n, i):
                    isPrime[j] = False
        return isPrime

class Solution:

    def maxPotholes(self, road, budget):
        ans = 0
        for length in sorted(map(len, road.split('.')), reverse=True):
            canRepair = max(0, budget - 1)
            if length > canRepair:
                return ans + canRepair
            ans += length
            budget -= length + 1
        return ans

