class Solution:

    def minimumOperations(self, grid):
        m = len(grid)
        n = len(grid[0])
        count = [[0] * 10 for _ in range(n)]
        for row in grid:
            for j, num in enumerate(row):
                count[j][num] += 1

        @functools.lru_cache(None)
        def dp(i, prev):
            """
      Returns the number of minimum operations needed to make grid[:][j..n)
      satisfy the conditions, where the (j - 1)-th column is filled with `prev`.
      """
            if i == n:
                return 0
            res = math.inf
            for num in range(10):
                if i == 0 or num != prev:
                    res = min(res, m - count[i][num] + dp(i + 1, num))
            return res
        return dp(0, 0)

class Solution:

    def findAnswer(self, n, edges):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        from0 = self._dijkstra(graph, 0)
        from1 = self._dijkstra(graph, n - 1)
        return [from0[u] + w + from1[v] == from0[-1] or from0[v] + w + from1[u] == from0[-1] for u, v, w in edges]

    def _dijkstra(self, graph, src):
        dist = [10 ** 9] * len(graph)
        dist[src] = 0
        minHeap = [(dist[src], src)]
        while minHeap:
            d, u = heapq.heappop(minHeap)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(minHeap, (dist[v], v))
        return dist

