class Solution:

    def canMakeSquare(self, grid):
        for i in range(2):
            for j in range(2):
                black = 0
                white = 0
                for x in range(2):
                    for y in range(2):
                        if grid[i + x][j + y] == 'B':
                            black += 1
                        else:
                            white += 1
                if black >= 3 or white >= 3:
                    return bool(True)
        return bool(False)

class Solution:

    def numberOfRightTriangles(self, grid):
        rows = [0] * len(grid)
        cols = [0] * len(grid[0])
        for i, row in enumerate(grid):
            for j, num in enumerate(row):
                if num == 1:
                    rows[i] += 1
                    cols[j] += 1
        return sum(((rows[i] - 1) * (cols[j] - 1) for i, row in enumerate(grid) for j, num in enumerate(row) if num == 1))

class Solution:

    def numberOfStableArrays(self, zero, one, limit):
        MOD = 1000000007
        dp = [[[0] * 2 for _ in range(one + 1)] for _ in range(zero + 1)]
        for i in range(min(zero, limit) + 1):
            dp[i][0][0] = 1
        for j in range(min(one, limit) + 1):
            dp[0][j][1] = 1
        for i in range(1, zero + 1):
            for j in range(1, one + 1):
                dp[i][j][0] = (dp[i - 1][j][0] + dp[i - 1][j][1] - (dp[i - limit - 1][j][1] if i - limit >= 1 else 0) + MOD) % MOD
                dp[i][j][1] = (dp[i][j - 1][0] + dp[i][j - 1][1] - (dp[i][j - limit - 1][0] if j - limit >= 1 else 0) + MOD) % MOD
        return (dp[zero][one][0] + dp[zero][one][1]) % MOD

