class Solution:

    def minimumAddedInteger(self, nums1, nums2):
        ans = math.inf
        nums1.sort()
        nums2.sort()
        for i in range(3):
            inc = nums2[0] - nums1[i]
            if self._isValidDiff(nums1, nums2, inc):
                ans = min(ans, inc)
        return ans

    def _isValidDiff(self, nums1, nums2, inc):
        """
    Returns True if it's possible to increase nums1 (with two elements removed)
    by `inc` to nums2.
    """
        removed = 0
        i = 0
        for num in nums1:
            if num + inc == nums2[i]:
                i += 1
                if i == len(nums2):
                    break
            else:
                removed += 1
        return bool(removed <= 2)

class Solution:

    def minEnd(self, n, x):
        MAX_BIT = n.bit_length() + x.bit_length()
        k = n - 1
        BINARY_INDEX = 0
        for i in range(MAX_BIT):
            if x >> i & 1 == 0:
                if k >> BINARY_INDEX & 1:
                    x |= 1 << i
                BINARY_INDEX += 1
        return x

class Solution:

    def medianOfUniquenessArray(self, nums):
        n = len(nums)
        subarrayCount = n * (n + 1) // 2
        medianCount = (subarrayCount + 1) // 2

        def subarraysWithAtMostKDistinct(k):
            res = 0
            count = collections.Counter()
            l = 0
            for r, num in enumerate(nums):
                count[num] += 1
                if count[num] == 1:
                    k -= 1
                while k < 0:
                    count[nums[l]] -= 1
                    if count[nums[l]] == 0:
                        k += 1
                    l += 1
                res += r - l + 1
            return res
        l = 1
        r = n
        return bisect_left(range(l, r), medianCount, key=subarraysWithAtMostKDistinct) + l

class Solution:

    def minOperations(self, initial, target):
        m = len(initial)
        n = len(target)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if initial[i - 1] == target[j - 1]:
                    dp[i][j] = 1 + dp[i - 1][j - 1]
        return m + n - 2 * max(map(max, dp))

