class Solution:

    def minAnagramLength(self, s):
        n = len(s)
        for k in range(1, n + 1):
            if n % k == 0 and self._canFormAnagram(s, k):
                return k
        return n

    def _canFormAnagram(self, s, k):
        """Returns True if we can concatenate an anagram of length k to s."""
        anagramCount = collections.Counter(s[:k])
        return bool(all((collections.Counter(s[i:i + k]) == anagramCount for i in range(k, len(s), k))))

class Solution:

    def maxHammingDistances(self, nums, m):
        MAX_MASK = 1 << m
        dp = [-math.inf] * MAX_MASK
        for num in nums:
            dp[num] = 0
        for bit in range(m):
            newDp = [0] * MAX_MASK
            for mask in range(MAX_MASK):
                newDp[mask] = max(dp[mask], dp[mask ^ 1 << bit] + 1)
            dp = newDp
        return [dp[num] for num in nums]

