        return bool(all((grid[i][j] == grid[i + 1][j] for i in range(m - 1) for j in range(n))) and all((grid[i][j] != grid[i][j + 1] for i in range(m) for j in range(n - 1))))

class Solution:

    def maxPointsInsideSquare(self, points, s):
        secondMinSize = math.inf
        minSizes = {}
        for (x, y), c in zip(points, s):
            sz = max(abs(x), abs(y))
            if c not in minSizes:
                minSizes[c] = sz
            elif sz < minSizes[c]:
                secondMinSize = min(secondMinSize, minSizes[c])
                minSizes[c] = sz
            else:
                secondMinSize = min(secondMinSize, sz)
        return sum((sz < secondMinSize for sz in minSizes.values()))

class Solution:

    def minimumSubstringsInPartition(self, s):
        n = len(s)
        dp = [n] * n
        for i in range(n):
            count = collections.Counter()
            for j in range(i, -1, -1):
                count[s[j]] += 1
                if min(count.values()) == max(count.values()):
                    dp[i] = min(dp[i], 1 + dp[j - 1] if j > 0 else 1)
        return dp[-1]

class Solution:

    def findProductsOfElements(self, queries):

        def sumBitsTill(x):
            """Returns sum(i.bit_count()), where 1 <= i <= x."""
            sumBits = 0
            powerOfTwo = 1
            while powerOfTwo <= x:
                sumBits += x // (2 * powerOfTwo) * powerOfTwo
                sumBits += max(0, x % (2 * powerOfTwo) + 1 - powerOfTwo)
                powerOfTwo *= 2
            return sumBits

        def sumPowersTill(x):
            """Returns sum(all powers of i), where 1 <= i <= x."""
            sumPowers = 0
            powerOfTwo = 1
            for power in range(x.bit_length()):
                sumPowers += x // (2 * powerOfTwo) * powerOfTwo * power
                sumPowers += max(0, x % (2 * powerOfTwo) + 1 - powerOfTwo) * power
                powerOfTwo *= 2
            return sumPowers

        def sumPowersFirstKBigNums(k):
            """Returns the sum of powers of the first k numbers in `big_nums`."""
            num = bisect_left(range(k), k, key=sumBitsTill)
            sumPowers = sumPowersTill(num - 1)
            remainingCount = k - sumBitsTill(num - 1)
            for power in range(num.bit_length()):
                if num >> power & 1:
                    sumPowers += power
                    remainingCount -= 1
                    if remainingCount == 0:
                        break
            return sumPowers
        return [pow(2, sumPowersFirstKBigNums(b + 1) - sumPowersFirstKBigNums(a), mod) for a, b, mod in queries]

