class Solution:

    def maximumEnergy(self, energy, k):
        dp = energy.copy()
        for i in range(len(energy) - 1 - k, -1, -1):
            dp[i] += dp[i + k]
        return max(dp)

class Solution:

    def maxScore(self, grid):
        MAX = 200000
        ans = -MAX
        for i, row in enumerate(grid):
            for j, num in enumerate(row):
                prevMin = min(grid[i - 1][j] if i > 0 else MAX, grid[i][j - 1] if j > 0 else MAX)
                ans = max(ans, num - prevMin)
                grid[i][j] = min(num, prevMin)
        return ans

class Solution:

    def findPermutation(self, nums):
        n = len(nums)
        bestPick = [[0] * (1 << n) for _ in range(n)]

        @functools.lru_cache(None)
        def getScore(last, mask):
            if mask.bit_count() == len(nums):
                return abs(last - nums[0])
            minScore = math.inf
            for i in range(1, len(nums)):
                if mask >> i & 1:
                    continue
                nextMinScore = abs(last - nums[i]) + getScore(i, mask | 1 << i)
                if nextMinScore < minScore:
                    minScore = nextMinScore
                    bestPick[last][mask] = i
            return minScore
        getScore(0, 1)
        return self._construct(bestPick)

    def _construct(self, bestPick):
        ans = []
        last = 0
        mask = 1
        for _ in range(len(bestPick)):
            ans.append(last)
            last = bestPick[last][mask]
            mask |= 1 << last
        return ans

import pandas as pd

def find_invalid_tweets(tweets):
    invalid_tweets = tweets[(tweets['content'].str.len() > 140) | (tweets['content'].str.count('@') > 3) | (tweets['content'].str.count('#') > 3)].sort_values(by='tweet_id')
    return invalid_tweets[['tweet_id']]

class Solution:
    def run(self, tables):
        tweets = _table_frame(list(tables.values())[0],list(tables)[0])
        result = find_invalid_tweets(tweets)
        if isinstance(result, pd.DataFrame):
            if result.index.name is not None:
                result = result.reset_index()
            return [{key:_table_value(value) for key,value in row.items()} for row in result.to_dict(orient="records")]
        return result

class Solution:

