class Solution:

    def isArraySpecial(self, nums, queries):
        ans = []
        id = 0
        parityIds = [id]
        for a, b in itertools.pairwise(nums):
            if a % 2 == b % 2:
                id += 1
            parityIds.append(id)
        for _from, to in queries:
            ans.append(parityIds[_from] == parityIds[to])
        return ans

class Solution:

    def sumDigitDifferences(self, nums):
        n = len(nums)
        digitSize = len(str(nums[0]))
        ans = 0
        denominator = 1
        for _ in range(digitSize):
            count = [0] * 10
            for num in nums:
                count[num // denominator % 10] += 1
            ans += sum((freq * (n - freq) for freq in count))
            denominator *= 10
        return ans // 2

class Solution:

    def waysToReachStair(self, k):
        MAX_JUMP = 29
        ans = 0
        for jump in range(MAX_JUMP + 1):
            down = (1 << jump) - k
            if down < 0 or down > jump + 1:
                continue
            ans += math.comb(jump + 1, down)
        return ans

class Solution:

    def maxUpgrades(self, count, upgrade, sell, money):
