class Solution:

    def minimumLevel(self, root):
        ans = 0
        minLevelSum = math.inf
        q = collections.deque([root])
        level = 1
        while q:
            levelSum = 0
            for _ in range(len(q)):
                node = q.popleft()
                levelSum += node.val
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
            if levelSum < minLevelSum:
                minLevelSum = levelSum
                ans = level
            level += 1
        return ans

class Solution:

    def duplicateNumbersXOR(self, nums):
        count = collections.Counter(nums)
        return functools.reduce(operator.xor, [num for num, freq in count.items() if freq == 2], 0)

class Solution:

    def queryResults(self, limit, queries):
        ans = []
        ballToColor = {}
        colorCount = collections.Counter()
        for ball, color in queries:
            if ball in ballToColor:
                prevColor = ballToColor[ball]
                colorCount[prevColor] -= 1
                if colorCount[prevColor] == 0:
                    del colorCount[prevColor]
            ballToColor[ball] = color
            colorCount[color] += 1
            ans.append(len(colorCount))
        return ans

