class Solution:

    def numberOfPairs(self, nums1, nums2, k):
        count = collections.Counter((num * k for num in nums2))
        ans = 0
        for num in nums1:
            for divisor in range(1, int(num ** 0.5) + 1):
                if num % divisor == 0:
                    ans += count[divisor]
                    if num // divisor != divisor:
                        ans += count[num // divisor]
        return ans

def max(a, b):
    return a if a > b else b

class Node:
    __slots__ = ('l', 'r', 's00', 's01', 's10', 's11')

    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.s00 = self.s01 = self.s10 = self.s11 = 0

class SegmentTree:
    __slots__ = 'tr'

    def __init__(self, n):
        self.tr = [None] * (n << 2)
        self.build(1, 1, n)

    def build(self, u, l, r):
        self.tr[u] = Node(l, r)
        if l == r:
            return
        mid = l + r >> 1
        self.build(u << 1, l, mid)
        self.build(u << 1 | 1, mid + 1, r)

    def query(self, u, l, r):
        if self.tr[u].l >= l and self.tr[u].r <= r:
            return self.tr[u].s11
        mid = self.tr[u].l + self.tr[u].r >> 1
        ans = 0
        if r <= mid:
            ans = self.query(u << 1, l, r)
        if l > mid:
            ans = max(ans, self.query(u << 1 | 1, l, r))
        return ans

    def pushup(self, u):
        left, right = (self.tr[u << 1], self.tr[u << 1 | 1])
        self.tr[u].s00 = max(left.s00 + right.s10, left.s01 + right.s00)
        self.tr[u].s01 = max(left.s00 + right.s11, left.s01 + right.s01)
        self.tr[u].s10 = max(left.s10 + right.s10, left.s11 + right.s00)
        self.tr[u].s11 = max(left.s10 + right.s11, left.s11 + right.s01)

    def modify(self, u, x, v):
        if self.tr[u].l == self.tr[u].r:
            self.tr[u].s11 = max(0, v)
            return
        mid = self.tr[u].l + self.tr[u].r >> 1
        if x <= mid:
            self.modify(u << 1, x, v)
        else:
            self.modify(u << 1 | 1, x, v)
        self.pushup(u)

class Solution:

    def maximumSumSubsequence(self, nums, queries):
        n = len(nums)
        tree = SegmentTree(n)
        for i, x in enumerate(nums, 1):
            tree.modify(1, i, x)
        ans = 0
        mod = 10 ** 9 + 7
        for i, x in queries:
            tree.modify(1, i + 1, x)
            ans = (ans + tree.query(1, 1, n)) % mod
        return ans

class Solution:

    def betterCompression(self, compressed):
        count = collections.Counter()
        i = 0
        while i < len(compressed):
            c = compressed[i]
            i += 1
            freq = 0
            while i < len(compressed) and compressed[i].isdigit():
                freq = freq * 10 + int(compressed[i])
                i += 1
            count[c] += freq
        return ''.join([c + str(count[c]) for c in sorted(count.keys())])

