        MOD = 1000000007
        dp = [1] + [0] * n
        for coin in (1, 2, 6):
            for i in range(coin, n + 1):
                dp[i] = (dp[i] + dp[i - coin]) % MOD
        ans = dp[n]
        if n - 4 >= 0:
            ans = (ans + dp[n - 4]) % MOD
        if n - 8 >= 0:
            ans = (ans + dp[n - 8]) % MOD
        return ans

