class Solution:

    def minFlips(self, grid):
        m = len(grid)
        n = len(grid[0])
        ans = 0
        middleOnes = 0
        mismatchedPairs = 0
        for i in range(m // 2):
            for j in range(n // 2):
                ones = grid[i][j] + grid[i][n - 1 - j] + grid[m - 1 - i][j] + grid[m - 1 - i][n - 1 - j]
                ans += min(ones, 4 - ones)
        if m % 2 == 1:
            for j in range(n // 2):
                leftCell = grid[m // 2][j]
                rightCell = grid[m // 2][n - 1 - j]
                mismatchedPairs += leftCell ^ rightCell
                middleOnes += leftCell + rightCell
        if n % 2 == 1:
            for i in range(m // 2):
                topCell = grid[i][n // 2]
                bottomCell = grid[m - 1 - i][n // 2]
                mismatchedPairs += topCell ^ bottomCell
                middleOnes += topCell + bottomCell
        if mismatchedPairs == 0:
            if middleOnes % 4 == 2:
                ans += 2
        else:
