class Solution:

    def __init__(self):
        self.SIZE = 50
        self.MAX = 1000000
        self.DIRS = ((1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2))

    def maxMoves(self, kx, ky, positions):
        n = len(positions)
        positions.append([kx, ky])
        hashedPositionToIndex = {}
        dist = [[0] * (n + 1) for _ in range(n + 1)]
        for i, (x, y) in enumerate(positions):
            hashedPositionToIndex[self._hash(x, y)] = i
        for sourceIndex in range(n + 1):
            self._bfs(positions, sourceIndex, hashedPositionToIndex, dist)
        MAX_MASK = 1 << n + 1
        dp = [[[0, 0] for _ in range(1 << n + 1)] for _ in range(n + 1)]
        for i in range(n + 1):
            for mask in range(MAX_MASK - 1):
                dp[i][mask] = [-self.MAX, self.MAX]
        for mask in range(MAX_MASK - 2, -1, -1):
            for i in range(n + 1):
                for turn in range(2):
                    for j in range(n):
                        if mask >> j & 1:
                            continue
                        moves = dist[i][j] + dp[j][mask | 1 << j][1 - turn]
                        dp[i][mask][turn] = max(dp[i][mask][turn], moves) if turn == 0 else min(dp[i][mask][turn], moves)
        return dp[n][1 << n][0]

    def _hash(self, x, y):
        return x * self.SIZE + y

    def _bfs(self, positions, sourceIndex, hashedPositionToIndex, dist):
        """
    Computes the distance between positions[sourceIndex] and other positions.
    """
        sx, sy = positions[sourceIndex]
        q = collections.deque([(sx, sy)])
        seen = {(sx, sy)}
        seenPositions = 0
        step = 0
        while q and seenPositions < len(positions):
            for _ in range(len(q)):
                i, j = q.popleft()
                hashedPosition = self._hash(i, j)
                if hashedPosition in hashedPositionToIndex:
                    dist[sourceIndex][hashedPositionToIndex[hashedPosition]] = step
                    seenPositions += 1
                for dx, dy in self.DIRS:
                    x = i + dx
                    y = j + dy
                    if x < 0 or x >= self.SIZE or y < 0 or (y >= self.SIZE):
                        continue
                    if (x, y) in seen:
                        continue
                    q.append((x, y))
                    seen.add((x, y))
            step += 1

class Solution:

    def getSum(self, nums):

        def getSum(diff):
            """Returns the sum of all subarrays with a difference of `diff`."""
            res = nums[0]
            summ = nums[0]
            count = 1
            for prev, num in itertools.pairwise(nums):
                if num == prev + diff:
                    count += 1
                    summ += count * num
                else:
                    count = 1
                    summ = num
                res += summ
            return res
        return (getSum(1) + getSum(-1) - sum(nums)) % 1000000007

