            maxMatchSuffix = 0
            for lps, word in zip(lpsList, words):
                maxMatchSuffix = max(maxMatchSuffix, lps[len(word) + unmatchedPrefix])
            if maxMatchSuffix == 0:
                return -1
            ans += 1
            unmatchedPrefix -= maxMatchSuffix
        return ans

