def calculate_final_prices(products, discounts):
    merged_df = pd.merge(products, discounts, on='category', how='left')
    merged_df['final_price'] = merged_df['price'] * (100 - merged_df['discount'].fillna(0)) / 100
    result_df = merged_df[['product_id', 'final_price', 'category']].sort_values('product_id')
    return result_df

