class Solution:
    def run(self, head, node):
        nodes=[DoublyNode(value) for value in head]
        for i,current in enumerate(nodes):
            current.prev=nodes[i-1] if i else None
            current.next=nodes[i+1] if i+1<len(nodes) else None
        current=next(current for current in nodes if current.val==node)
        while current.prev:
            current=current.prev
        answer=[]
        while current:
            answer.append(current.val)
            current=current.next
        return answer

