class Solution:

    def minNumberOfSeconds(self, mountainHeight, workerTimes):

        def getReducedHeight(m):
            """Returns the total height reduced by all workers in `m` seconds."""
            return sum(((-1 + math.sqrt(1 + 8 * m // workerTime)) // 2 for workerTime in workerTimes))
        l = 1
        r = min(workerTimes) * mountainHeight * (mountainHeight + 1) // 2
        return bisect_left(range(l, r), mountainHeight, key=getReducedHeight) + l

class Solution:

    def validSubstringCount(self, word1, word2):
        ans = 0
        count = collections.Counter(word2)
        required = len(word2)
        l = 0
        for r, c in enumerate(word1):
            count[c] -= 1
            if count[c] >= 0:
                required -= 1
            while required == 0:
                ans += len(word1) - r
                count[word1[l]] += 1
                if count[word1[l]] > 0:
                    required += 1
                l += 1
        return ans

