class Solution:

    def maxRemovals(self, source, pattern, targetIndices):
        m = len(source)
        n = len(pattern)
        target = set(targetIndices)

        @functools.lru_cache(None)
        def dp(i, j):
            """
      Returns the maximum number of operations that can be performed for
      source[i..m) and pattern[j..n).
      """
            if i == m:
                return 0 if j == n else -math.inf
            if j == n:
                return int(i in target) + dp(i + 1, j)
            pick = dp(i + 1, j + 1) if source[i] == pattern[j] else -math.inf
            skip = int(i in target) + dp(i + 1, j)
            return max(pick, skip)
        ans = dp(0, 0)
        return 0 if ans == -math.inf else ans

class Solution:

    def numberOfWays(self, n, x, y):
        MOD = 1000000007

        @functools.lru_cache(None)
        def fact(i):
            return 1 if i <= 1 else i * fact(i - 1) % MOD

        @functools.lru_cache(None)
        def inv(i):
            return pow(i, MOD - 2, MOD)

        @functools.lru_cache(None)
        def nCk(n, k):
            return fact(n) * inv(fact(k)) * inv(fact(n - k)) % MOD

        @functools.lru_cache(None)
        def stirling(n, k):
            """
      Returns the number of ways to partition a set of n objects into k
      non-empty subsets.

      https://en.wikipedia.org/wiki/Stirling_numbers_of_the_second_kind
      """
            if k == 0 or n < k:
                return 0
            if k == 1 or n == k:
                return 1
            return (k * stirling(n - 1, k) + stirling(n - 1, k - 1)) % MOD
        return sum((nCk(x, k) * stirling(n, k) * fact(k) * pow(y, k, MOD) % MOD for k in range(1, min(n, x) + 1))) % MOD

class Solution:

    def findXSum(self, nums, k, x):
        ans = []
        windowSum = 0
        count = collections.Counter()
        top = SortedList()
        bot = SortedList()

        def update(num, freq):
            """Updates the count of num by freq and the window sum accordingly."""
            nonlocal windowSum
            if count[num] > 0:
                if [count[num], num] in bot:
                    bot.remove([count[num], num])
                else:
                    top.remove([count[num], num])
                    windowSum -= num * count[num]
            count[num] += freq
            if count[num] > 0:
                bot.add([count[num], num])
        for i, num in enumerate(nums):
            update(num, 1)
            if i >= k:
                update(nums[i - k], -1)
            while bot and len(top) < x:
                countB, b = bot.pop()
                top.add([countB, b])
                windowSum += b * countB
            while bot and bot[-1] > top[0]:
                countB, b = bot.pop()
                countT, t = top.pop(0)
                bot.add([countT, t])
                windowSum -= t * countT
                top.add([countB, b])
                windowSum += b * countB
            if i >= k - 1:
                ans.append(windowSum)
        return ans

from dataclasses import dataclass

@dataclass(frozen=True)
class T:
    isPerfect: bool
    sz: int

class Solution:

    def kthLargestPerfectSubtree(self, root, k):
        ans = []
        self._dfs(root, ans)
        if len(ans) < k:
            return -1
        return sorted(ans, reverse=True)[k - 1]

    def _dfs(self, root, ans):
        if not root:
            return T(True, 0)
        l = self._dfs(root.left, ans)
        r = self._dfs(root.right, ans)
        if l.isPerfect and r.isPerfect and (l.sz == r.sz):
            sz = 1 + l.sz + r.sz
            ans.append(sz)
            return T(True, sz)
        return T(False, 0)

class Solution:

    def countWinningSequences(self, s):
        MOD = 1000000007

        @functools.lru_cache(None)
        def dp(i, prev, bob):
            """
      Returns the number of distinct sequences Bob can use to beat Alice for
      s[i..n), where the previous character is `prev` (0: F, 1: W, 2: E) and the
      number of points that Bob is having is `bob`.
      """
            if i == len(s):
                return int(bob > 0)
            f = 0
            w = 0
            e = 0
            match s[i]:
                case 'F':
                    if prev != 0:
                        f = dp(i + 1, 0, bob) % MOD
                    if prev != 1:
                        w = dp(i + 1, 1, bob + 1) % MOD
                    if prev != 2:
                        e = dp(i + 1, 2, bob - 1) % MOD
                case 'W':
                    if prev != 0:
                        f = dp(i + 1, 0, bob - 1) % MOD
                    if prev != 1:
                        w = dp(i + 1, 1, bob) % MOD
                    if prev != 2:
                        e = dp(i + 1, 2, bob + 1) % MOD
                case 'E':
                    if prev != 0:
                        f = dp(i + 1, 0, bob + 1) % MOD
                    if prev != 1:
                        w = dp(i + 1, 1, bob - 1) % MOD
                    if prev != 2:
                        e = dp(i + 1, 2, bob) % MOD
            return f + w + e
        return (dp(0, 0, 0) + dp(0, 1, 0) + dp(0, 2, 0)) // 2 % MOD

