class Solution:

    def numberOfSubstrings(self, s, k):
        n = len(s)
        ans = n * (n + 1) // 2
        count = collections.Counter()
        l = 0
        for r, c in enumerate(s):
            count[c] += 1
            while count[c] == k:
                count[s[l]] -= 1
                l += 1
            ans -= r - l + 1
        return ans

class Solution:

    def minOperations(self, nums):
        ans = 0
        for i in range(len(nums) - 2, -1, -1):
            if nums[i] > nums[i + 1]:
                minDivisor = self._getMinDivisor(nums[i])
                if minDivisor > nums[i + 1]:
                    return -1
                nums[i] = minDivisor
                ans += 1
        return ans

    def _getMinDivisor(self, num):
        for divisor in range(2, math.isqrt(num) + 1):
            if num % divisor == 0:
                return divisor
        return num

