class Solution:

    def maxScore(self, n, k, stayScore, travelScore):
        dp = [[0] * n for _ in range(k + 1)]
        for i in range(1, k + 1):
            for dest in range(n):
                dp[i][dest] = dp[i - 1][dest] + stayScore[i - 1][dest]
                for curr in range(n):
                    if curr != dest:
                        dp[i][dest] = max(dp[i][dest], dp[i - 1][curr] + travelScore[curr][dest])
        return max(dp[k])

class Solution:

    def lengthAfterTransformations(self, s, t):
        MOD = 1000000007
        count = [0] * 26
        for c in s:
            count[ord(c) - ord('a')] += 1
        for _ in range(t):
            newCount = [0] * 26
            for i in range(25):
                newCount[i + 1] = count[i]
            newCount[0] = count[25]
            newCount[1] = (newCount[1] + count[25]) % MOD
            count = newCount
        return sum(count) % MOD

class Solution:
    def run(self, s, t, nums):
        mod=1000000007
        transition=np.zeros((26,26),dtype=object)
        for i,count in enumerate(nums):
            for offset in range(1,count+1):
                transition[i][(i+offset)%26]+=1
        counts=np.array([s.count(chr(97+i)) for i in range(26)],dtype=object)
        while t:
            if t&1:
                counts=(counts@transition)%mod
            transition=(transition@transition)%mod
            t//=2
        return int(sum(counts)%mod)

