class Solution:

    def countOfArrays(self, n, m, k):
        MOD = 10 ** 9 + 7
        even = m // 2
        odd = m - even
        dp = [[[0] * 2 for _ in range(k + 1)] for _ in range(n + 1)]
        dp[1][0][0] = even
        dp[1][0][1] = odd
        for i in range(2, n + 1):
            for j in range(k + 1):
                dp[i][j][0] = ((dp[i - 1][j - 1][0] if j > 0 else 0) * even + dp[i - 1][j][1] * even) % MOD
                dp[i][j][1] = sum(dp[i - 1][j]) * odd % MOD
        return sum(dp[n][k]) % MOD

