class Solution:

    def countValidSelections(self, nums):
        ans = 0
        prefix = list(itertools.accumulate(nums))
        suffix = list(itertools.accumulate(nums[::-1]))[::-1]
        for i, num in enumerate(nums):
            if num > 0:
                continue
            if prefix[i] == suffix[i]:
                ans += 2
            if abs(prefix[i] - suffix[i]) == 1:
                ans += 1
        return ans

class Solution:

    def minDifference(self, nums):
        maxPositiveGap = 0
        mn = 1000000000
        mx = 0
        for a, b in itertools.pairwise(nums):
            if (a == -1) != (b == -1):
                positive = max(a, b)
                mn = min(mn, positive)
                mx = max(mx, positive)
            else:
                maxPositiveGap = max(maxPositiveGap, abs(a - b))
        l = maxPositiveGap
        r = (mx - mn + 1) // 2
        return bisect_left(range(l, r), True, key=lambda m: self._check(nums, m, mn + m, mx - m)) + l

    def _check(self, nums, m, x, y):
        """
    Returns True if it's possible have `m` as maximum absolute difference
    between adjacent numbers, where -1s are replaced with `x` or `y`.
    """
        gapLength = 0
        prev = 0
        for num in nums:
            if num == -1:
                gapLength += 1
                continue
            if prev > 0 and gapLength > 0:
                if gapLength == 1 and (not self._checkSingleGap(prev, num, m, x, y)):
                    return bool(False)
                if gapLength > 1 and (not self._checkMultipleGaps(prev, num, m, x, y)):
                    return bool(False)
            prev = num
            gapLength = 0
        if nums[0] == -1:
            num = next((num for num in nums if num != -1), -1)
            if num != -1 and (not self._checkBoundaryGaps(num, m, x, y)):
                return bool(False)
        if nums[-1] == -1:
            num = next((num for num in reversed(nums) if num != -1), -1)
            if num != -1 and (not self._checkBoundaryGaps(num, m, x, y)):
                return bool(False)
        return bool(True)

    def _checkSingleGap(self, a, b, m, x, y):
        """
    Returns true if it's possible to have at most `m` as the minimized maximum
    difference for a sequence with a single -1 between two numbers.
    e.g. [a, -1, b] can be filled with either x or y.
    """
        gapWithX = max(abs(a - x), abs(b - x))
        gapWithY = max(abs(a - y), abs(b - y))
        return bool(min(gapWithX, gapWithY) <= m)

    def _checkMultipleGaps(self, a, b, m, x, y):
        """
    Returns true if it's possible to have at most `m` as the minimized maximum
    difference for a sequence with multiple -1s between two numbers.
    e.g. [a, -1, -1, ..., -1, b] can be filled with x and y.
    """
        ax = abs(a - x)
        ay = abs(a - y)
        bx = abs(b - x)
        by = abs(b - y)
        xy = abs(x - y)
        gapAllX = max(ax, bx)
        gapAllY = max(ay, by)
        gapXToY = max(ax, xy, by)
        gapYToX = max(ay, xy, bx)
        return bool(min(gapAllX, gapAllY, gapXToY, gapYToX) <= m)

    def _checkBoundaryGaps(self, a, m, x, y):
        """
    Returns true if it's possible to have at most `m` as the minimized maximum
    difference for a boundary sequence starting or ending with -1s.
    e.g. [a, -1, -1, ...] or [..., -1, -1, a].
    """
        gapAllX = abs(a - x)
        gapAllY = abs(a - y)
        return bool(min(gapAllX, gapAllY) <= m)

