class Solution:

    def shiftDistance(self, s, t, nextCost, previousCost):
        ans = 0
        prev = [[0] * 26 for _ in range(26)]
        next = [[0] * 26 for _ in range(26)]
        for i in range(26):
            cost = 0
            for j in range(26):
                next[i][(i + j) % 26] = cost
                cost += nextCost[(i + j) % 26]
        for i in range(26):
            cost = 0
            for j in range(26):
                prev[i][(i - j + 26) % 26] = cost
                cost += previousCost[(i - j + 26) % 26]
        for a, b in zip(s, t):
            i = ord(a) - ord('a')
            j = ord(b) - ord('a')
            ans += min(next[i][j], prev[i][j])
        return ans

class Solution:

    def maxCollectedFruits(self, fruits):
        n = len(fruits)

        def getTopLeft():
            return sum((fruits[i][i] for i in range(n)))

        def getTopRight():
            dp = [[0] * n for _ in range(n)]
            dp[0][-1] = fruits[0][-1]
            for x in range(n):
                for y in range(n):
                    if x >= y and (x, y) != (n - 1, n - 1):
                        continue
                    for dx, dy in [(1, -1), (1, 0), (1, 1)]:
                        i = x - dx
                        j = y - dy
                        if i < 0 or i == n or j < 0 or (j == n):
                            continue
                        if i < j < n - 1 - i:
                            continue
                        dp[x][y] = max(dp[x][y], dp[i][j] + fruits[x][y])
            return dp[-1][-1]

        def getBottomLeft():
            dp = [[0] * n for _ in range(n)]
            dp[-1][0] = fruits[-1][0]
            for y in range(n):
                for x in range(n):
                    if x <= y and (x, y) != (n - 1, n - 1):
                        continue
                    for dx, dy in [(-1, 1), (0, 1), (1, 1)]:
                        i = x - dx
                        j = y - dy
                        if i < 0 or i == n or j < 0 or (j == n):
                            continue
                        if j < i < n - 1 - j:
                            continue
                        dp[x][y] = max(dp[x][y], dp[i][j] + fruits[x][y])
            return dp[-1][-1]
        return getTopLeft() + getTopRight() + getBottomLeft() - 2 * fruits[-1][-1]

