class Solution:

    def minArraySum(self, nums, k, op1, op2):

        @functools.lru_cache(None)
        def dp(i, op1, op2):
            """
      Returns the minimum sum of nums[i..n - 1] with `op1` operations of op1 and
      `op2` operations of op2.
      """
            if i == len(nums):
                return 0
            res = nums[i] + dp(i + 1, op1, op2)
            if op1 > 0:
                res = min(res, (nums[i] + 1) // 2 + dp(i + 1, op1 - 1, op2))
            if op2 > 0 and nums[i] >= k:
                res = min(res, nums[i] - k + dp(i + 1, op1, op2 - 1))
            if op1 > 0 and op2 > 0:
                if (nums[i] + 1) // 2 >= k:
                    res = min(res, (nums[i] + 1) // 2 - k + dp(i + 1, op1 - 1, op2 - 1))
                if nums[i] >= k:
                    res = min(res, (nums[i] - k + 1) // 2 + dp(i + 1, op1 - 1, op2 - 1))
            return res
        return dp(0, op1, op2)

class Solution:

    def maximizeSumOfWeights(self, edges, k):
        graph = [[] for _ in range(len(edges) + 1)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        def dfs(u, prev):
            """
      Returns
      (the weight sum of the subtree rooted at u with at most k - 1 children,
       the weight sum of the subtree rooted at u with at most k children).
      """
            weightSum = 0
            diffs = []
            for v, w in graph[u]:
                if v == prev:
                    continue
                subK1, subK = dfs(v, u)
                weightSum += subK
                diffs.append(max(0, subK1 - subK + w))
            return (weightSum + sum(heapq.nlargest(k - 1, diffs)), weightSum + sum(heapq.nlargest(k, diffs)))
        return dfs(0, -1)[1]

