class StatisticsTracker:

    def __init__(self):
        self.q = collections.deque()
        self.count = collections.Counter()
        self.sortedList = SortedList()
        self.modeMaxHeap = []
        self.sum = 0

    def addNumber(self, number):
        self.q.append(number)
        self.count[number] += 1
        self.sortedList.add(number)
        heapq.heappush(self.modeMaxHeap, (-self.count[number], number))
        self.sum += number

    def removeFirstAddedNumber(self):
        number = self.q.popleft()
        self.count[number] -= 1
        self.sortedList.remove(number)
        self.sum -= number

    def getMean(self):
        return self.sum // len(self.q)

    def getMedian(self):
        return self.sortedList[len(self.sortedList) // 2]

    def getMode(self):
        while self.modeMaxHeap:
            frequency = -self.modeMaxHeap[0][0]
            number = self.modeMaxHeap[0][1]
            if self.count[number] == frequency:
                return number
            heapq.heappop(self.modeMaxHeap)

class Solution:
    def run(self, operations, arguments):
        instance = StatisticsTracker(*arguments[0])
        answer = [None]
        for index, (operation, args) in enumerate(zip(operations[1:], arguments[1:]), 1):
            result = getattr(instance, operation)(*args)
            answer.append(deepcopy(result))
        return answer

