class Solution:

    def getLargestOutlier(self, nums):
        ans = -math.inf
        summ = sum(nums)
        count = collections.Counter(nums)
        for num in nums:
            withoutNum = summ - num
            if withoutNum % 2 == 0:
                specialSum = withoutNum // 2
                if count[specialSum] > (1 if num == specialSum else 0):
                    ans = max(ans, num)
        return ans

class Solution:

    def maxTargetNodes(self, edges1, edges2, k):
        graph1 = self._buildGraph(edges1)
        graph2 = self._buildGraph(edges2)
        maxReachableInGraph2 = 0
        if k > 0:
            for i in range(len(edges2) + 1):
                maxReachableInGraph2 = max(maxReachableInGraph2, self._dfs(graph2, i, -1, k - 1))
        return [maxReachableInGraph2 + self._dfs(graph1, i, -1, k) for i in range(len(edges1) + 1)]

    def _dfs(self, graph, u, prev, k):
        """Returns the number of nodes that can be reached from u with k steps."""
        if k == 0:
            return 1
        res = 0
        for v in graph[u]:
            if v != prev:
                res += self._dfs(graph, v, u, k - 1)
        return 1 + res

    def _buildGraph(self, edges):
        graph = [[] for _ in range(len(edges) + 1)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        return graph

