class Solution:

    def minOperations(self, n, m):
        isPrime = _prime_flags
        if isPrime[n] or isPrime[m]:
            return -1
        return self._dijkstra(n, m, isPrime)

    def _dijkstra(self, src, dst, isPrime):
        seen = {src}
        minHeap = [(src, src)]
        while minHeap:
            cost, curr = heapq.heappop(minHeap)
            if curr == dst:
                return cost
            s = list(str(curr))
            for i, c in enumerate(s):
                if c < '9':
                    s[i] = str(int(c) + 1)
                    nextNum = int(''.join(s))
                    if not isPrime[nextNum] and nextNum not in seen:
                        heapq.heappush(minHeap, (cost + nextNum, nextNum))
                        seen.add(nextNum)
                    s[i] = c
                if c > '0' and (not (i == 0 and c == '1')):
                    s[i] = str(int(c) - 1)
                    nextNum = int(''.join(s))
                    if not isPrime[nextNum] and nextNum not in seen:
                        heapq.heappush(minHeap, (cost + nextNum, nextNum))
                        seen.add(nextNum)
                    s[i] = c
        return -1

    def _sieveEratosthenes(self, n):
        isPrime = [True] * n
