class Solution:

    def beautifulSplits(self, nums):
        n = len(nums)
        z = [self._zFunction(nums, start) for start in range(n)]
        return sum((j - i >= i + 1 and z[0][i + 1] >= i + 1 or z[i + 1][j + 1] >= j - i for i in range(n - 2) for j in range(i + 1, n - 1)))

    def _zFunction(self, nums, start):
        """
    Returns the z array, where z[i] is the length of the longest prefix of
    nums[i..n) which is also a prefix of nums[start..n).
    """
        n = len(nums)
        z = [0] * n
        l = start
        r = start
        for i in range(1 + start, n):
            if i < r:
                z[i] = min(r - i, z[i - l + start])
            while i + z[i] < n and nums[z[i] + start] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > r:
                l = i
                r = i + z[i]
        return z

class Solution:

    def makeStringGood(self, s):
        count = [0] * 26
        for c in s:
            count[ord(c) - ord('a')] += 1
        return min((self._getMinOperations(count, target) for target in range(1, max(count) + 1)))

    def _getMinOperations(self, count, target):
        dp = [0] * 27
        for i in range(25, -1, -1):
            deleteAllToZero = count[i]
            deleteOrInsertToTarget = abs(target - count[i])
            dp[i] = min(deleteAllToZero, deleteOrInsertToTarget) + dp[i + 1]
            if i + 1 < 26 and count[i + 1] < target:
                nextDeficit = target - count[i + 1]
                needToChange = count[i] if count[i] <= target else count[i] - target
                changeToTarget = needToChange + (nextDeficit - needToChange) if nextDeficit > needToChange else nextDeficit + (needToChange - nextDeficit)
                dp[i] = min(dp[i], changeToTarget + dp[i + 2])
        return dp[0]

class Matrix3D:

    def __init__(self, n):
        self.isSet = set()
        self.count = collections.Counter()
        self.pairs = SortedList(key=lambda x: (-x[0], -x[1]))
        self.pairs.update(((0, x) for x in range(n)))

    def setCell(self, x, y, z):
        if (x, y, z) in self.isSet:
            return
        self.isSet.add((x, y, z))
        self.pairs.remove((self.count[x], x))
        self.count[x] += 1
        self.pairs.add((self.count[x], x))

    def unsetCell(self, x, y, z):
        if (x, y, z) not in self.isSet:
            return
        self.isSet.remove((x, y, z))
        self.pairs.remove((self.count[x], x))
        self.count[x] -= 1
        self.pairs.add((self.count[x], x))

    def largestMatrix(self):
        return self.pairs[0][1]

