class Solution:

    def minMaxSums(self, nums, k):
        MOD = 1000000007
        n = len(nums)

        def getComb(n, k):
            """C(n, k) = C(n - 1, k) + C(n - 1, k - 1)"""
            comb = [[0] * (k + 1) for _ in range(n + 1)]
            for i in range(n + 1):
                comb[i][0] = 1
            for i in range(1, n + 1):
                for j in range(1, k + 1):
                    comb[i][j] = (comb[i - 1][j] + comb[i - 1][j - 1]) % MOD
            return comb
        comb = getComb(n, k - 1)
        ans = 0
        nums.sort()
        for i in range(n):
            count = 0
            for j in range(k):
                count = (count + comb[i][j]) % MOD
            ans += nums[i] * count
            ans += nums[-1 - i] * count
            ans %= MOD
        return ans

