class Solution:

    def minimumIncrements(self, nums, target):
        maxMask = 1 << len(target)
        maskToLcm = {}
        for mask in range(1, maxMask):
            subset = [num for i, num in enumerate(target) if mask >> i & 1]
            maskToLcm[mask] = functools.reduce(math.lcm, subset, 1)
        dp = [math.inf] * maxMask
        dp[0] = 0
        for num in nums:
            maskToCost = [(mask, 0 if (remainder := (num % lcm)) == 0 else lcm - remainder) for mask, lcm in maskToLcm.items()]
            newDp = dp[:]
            for prevMask in range(maxMask):
                if dp[prevMask] == float('inf'):
                    continue
                for mask, cost in maskToCost:
                    newMask = prevMask | mask
                    newDp[newMask] = min(newDp[newMask], dp[prevMask] + cost)
            dp = newDp
        return -1 if dp[-1] == math.inf else dp[-1]

class Solution:

    def sortMatrix(self, grid):
        n = len(grid)
        ans = [[0] * n for _ in range(n)]
        diag = collections.defaultdict(list)
        for i, row in enumerate(grid):
            for j, num in enumerate(row):
                diag[i - j].append(num)
        for key in diag:
            diag[key].sort(reverse=key < 0)
        for i in range(n):
            for j in range(n):
                ans[i][j] = diag[i - j].pop()
        return ans

class Solution:

    def assignElements(self, groups, elements):
        ans = []
        elementToMinIndex = {}
        for i, element in enumerate(elements):
            if element not in elementToMinIndex:
                elementToMinIndex[element] = i
        for num in groups:
            ans.append(self._getMinIndex(num, elementToMinIndex))
        return ans

    def _getMinIndex(self, num, elementToMinIndex):
        res = math.inf
        for i in range(1,isqrt(num)+1):
            if num % i != 0:
                continue
            if i in elementToMinIndex:
                res = min(res, elementToMinIndex[i])
            if num // i != i and num // i in elementToMinIndex:
                res = min(res, elementToMinIndex[num // i])
        return -1 if res == math.inf else res

class Solution:

    def countSubstrings(self, s):
        ans = 0
        dp = [[[0] * 10 for _ in range(10)] for _ in range(len(s) + 1)]
        for i in range(1, len(s) + 1):
            digit = int(s[i - 1])
            for num in range(1, 10):
                for rem in range(num):
                    dp[i][num][(rem * 10 + digit) % num] += dp[i - 1][num][rem]
                dp[i][num][digit % num] += 1
            ans += dp[i][digit][0]
        return ans

class Solution:

    def maxScore(self, points, m):

        def isPossible(minVal, m):
            """
      Returns True if it is possible to achieve the maximum minimum value `x`
      with `m` number of moves.
      """
            moves = 0
            prevMoves = 0
            for i, point in enumerate(points):
                required = (minVal + point - 1) // point
                required = max(0, required - prevMoves)
                if required > 0:
                    moves += 2 * required - 1
                    prevMoves = required - 1
                elif i + 1 < len(points):
                    moves += 1
                    prevMoves = 0
                if moves > m:
                    return bool(False)
            return bool(True)
        l = 0
        r = (m + 1) // 2 * points[0] + 1
        while l < r:
            mid = (l + r + 1) // 2
            if isPossible(mid, m):
                l = mid
            else:
                r = mid - 1
        return l

class Solution:

