def find_invalid_ips(logs):

    def is_valid_ip(ip):
        octets = ip.split('.')
        if len(octets) != 4:
            return bool(False)
        for octet in octets:
            if not octet.isdigit():
                return bool(False)
            value = int(octet)
            if not 0 <= value <= 255 or octet != str(value):
                return bool(False)
        return bool(True)
    logs['is_valid'] = logs['ip'].apply(is_valid_ip)
    invalid_ips = logs[~logs['is_valid']]
    invalid_count = invalid_ips['ip'].value_counts().reset_index()
    invalid_count.columns = ['ip', 'invalid_count']
    result = invalid_count.sort_values(by=['invalid_count', 'ip'], ascending=[False, False])
    return result

