class Solution:

    def lenOfVDiagonal(self, grid):
        DIRS = ((-1, 1), (1, 1), (1, -1), (-1, -1))

        @functools.lru_cache(None)
        def dfs(i, j, turned, num, dir):
            if i < 0 or i == len(grid) or j < 0 or (j == len(grid[0])):
                return 0
            if grid[i][j] != num:
                return 0
            nextNum = 0 if num == 2 else 2
            dx, dy = DIRS[dir]
            res = 1 + dfs(i + dx, j + dy, turned, nextNum, dir)
            if not turned:
                nextDir = (dir + 1) % 4
                nextDx, nextDy = DIRS[nextDir]
                res = max(res, 1 + dfs(i + nextDx, j + nextDy, 1, nextNum, nextDir))
            return res
        return max((1 + dfs(i + dx, j + dy, 0, 2, d) for i, row in enumerate(grid) for j, num in enumerate(row) if num == 1 for d, (dx, dy) in enumerate(DIRS)), default=0)

class Solution:

    def longestCommonPrefix(self, s, t):
        i = 0
        j = 0
        canSkip = True
        while i < len(s) and j < len(t):
            if s[i] == t[j]:
                i += 1
                j += 1
            elif canSkip:
                i += 1
                canSkip = False
            else:
                return j
        return j

class Solution:

    def maxSum(self, grid, limits, k):
        minHeap = []
        for row, limit in zip(grid, limits):
            row.sort(reverse=True)
            for i in range(limit):
                heapq.heappush(minHeap, row[i])
                if len(minHeap) == k + 1:
                    heapq.heappop(minHeap)
        return sum(minHeap)

