class Solution:

    def minCost(self, nums):
        n = len(nums)

        @functools.lru_cache(None)
        def dp(last, i):
            if i == n:
                return nums[last]
            if i == n - 1:
                return max(nums[last], nums[i])
            a = max(nums[i], nums[i + 1]) + dp(last, i + 2)
            b = max(nums[last], nums[i]) + dp(i + 1, i + 2)
            c = max(nums[last], nums[i + 1]) + dp(i, i + 2)
            return min(a, b, c)
        return dp(0, 1)

class Solution:

    def permute(self, n, k):
        ans = []
        isLookingForEven = True
        remainingNumbers = list(range(1, n + 1))
        for turn in range(n):
            remainingPermutations = math.factorial((n - 1 - turn) // 2) * math.factorial((n - turn) // 2)
            found = False
            for index, number in enumerate(remainingNumbers):
                if number % 2 != isLookingForEven and (turn > 0 or n % 2 == 1):
                    continue
                if k <= remainingPermutations:
                    ans.append(remainingNumbers.pop(index))
                    isLookingForEven = ans[-1] % 2 == 0
                    found = True
                    break
                k -= remainingPermutations
            if not found:
                return []
        return ans

class Solution:

    def longestPalindromicSubsequence(self, s, k):

        @functools.lru_cache(None)
        def dp(i, j, op):
            """Returns the length of LPS(s[i..j]) with at most `op` operations."""
            if i > j:
                return 0
            if i == j:
                return 1
            if s[i] == s[j]:
                return 2 + dp(i + 1, j - 1, op)
            res = max(dp(i + 1, j, op), dp(i, j - 1, op))
            cost = self._getCost(s[i], s[j])
            if cost <= op:
                res = max(res, 2 + dp(i + 1, j - 1, op - cost))
            return res
        return dp(0, len(s) - 1, k)

    def _getCost(self, a, b):
        dist = abs(ord(a) - ord(b))
        return min(dist, 26 - dist)

class Solution:

    def maxSum(self, nums, k, m):
        INF = 20000000
        n = len(nums)
        prefix = list(itertools.accumulate(nums, initial=0))

        @functools.lru_cache(None)
        def dp(i, ongoing, k):
            if k < 0:
                return -INF
            if i == n:
                return 0 if k == 0 else -INF
            if ongoing == 1:
                return max(dp(i, 0, k), dp(i + 1, 1, k) + nums[i])
            res = dp(i + 1, 0, k)
            if i + m <= n:
                res = max(res, dp(i + m, 1, k - 1) + (prefix[i + m] - prefix[i]))
            return res
        return dp(0, 0, k)

class Solution:

    def generateString(self, str1, str2):
        n = len(str1)
        m = len(str2)
        sz = n + m - 1
        ans = [None] * sz
        modifiable = [True] * sz
        for i, tf in enumerate(str1):
            if tf == 'T':
                for j, c in enumerate(str2):
                    pos = i + j
                    if ans[pos] and ans[pos] != c:
                        return ''
                    ans[pos] = c
                    modifiable[pos] = False
        for i in range(sz):
            if not ans[i]:
                ans[i] = 'a'
        for i in range(n):
            if str1[i] == 'F' and self._match(ans, i, str2):
                modifiablePos = self._lastModifiablePosition(i, m, modifiable)
                if modifiablePos == -1:
                    return ''
                ans[modifiablePos] = 'b'
                modifiable[modifiablePos] = False
        return ''.join(ans)

    def _match(self, ans, i, s):
        """Returns True if the substring of ans starting at `i` matches `s`."""
        for j, c in enumerate(s):
            if ans[i + j] != c:
                return bool(False)
        return bool(True)

    def _lastModifiablePosition(self, i, m, modifiable):
        """
    Finds the last modifiable position in the substring of ans starting at `i`.
    """
        modifiablePos = -1
        for j in range(m):
            pos = i + j
            if modifiable[pos]:
                modifiablePos = pos
        return modifiablePos

