class Solution:

    def findMaxSum(self, nums1, nums2, k):
        ans = [0] * len(nums1)
        numAndIndexes = sorted([(num, i) for i, num in enumerate(nums1)])
        minHeap = []
        firstIndex = numAndIndexes[0][1]
        heapq.heappush(minHeap, nums2[firstIndex])
        summ = nums2[firstIndex]
        for (prevNum, prevIndex), (currNum, currIndex) in itertools.pairwise(numAndIndexes):
            if currNum == prevNum:
                ans[currIndex] = ans[prevIndex]
            else:
                ans[currIndex] = summ
            heapq.heappush(minHeap, nums2[currIndex])
            summ += nums2[currIndex]
            if len(minHeap) == k + 1:
                summ -= heapq.heappop(minHeap)
        return ans

class SegmentTree:
    __slots__ = ['nums', 'tr']

    def __init__(self, nums):
        self.nums = nums
        n = len(nums)
        self.tr = [0] * (n << 2)
        self.build(1, 1, n)

    def build(self, u, l, r):
        if l == r:
            self.tr[u] = self.nums[l - 1]
            return
        mid = l + r >> 1
        self.build(u << 1, l, mid)
        self.build(u << 1 | 1, mid + 1, r)
        self.pushup(u)

    def modify(self, u, l, r, i, v):
        if l == r:
            self.tr[u] = v
            return
        mid = l + r >> 1
        if i <= mid:
            self.modify(u << 1, l, mid, i, v)
        else:
            self.modify(u << 1 | 1, mid + 1, r, i, v)
        self.pushup(u)

    def query(self, u, l, r, v):
        if self.tr[u] < v:
            return -1
        if l == r:
            return l
        mid = l + r >> 1
        if self.tr[u << 1] >= v:
            return self.query(u << 1, l, mid, v)
        return self.query(u << 1 | 1, mid + 1, r, v)

    def pushup(self, u):
        self.tr[u] = max(self.tr[u << 1], self.tr[u << 1 | 1])

class Solution:

    def numOfUnplacedFruits(self, fruits, baskets):
        tree = SegmentTree(baskets)
        n = len(baskets)
        ans = 0
        for x in fruits:
            i = tree.query(1, 1, n, x)
            if i < 0:
                ans += 1
            else:
                tree.modify(1, 1, n, i, 0)
        return ans

class Solution:

    def maxSubarrays(self, n, conflictingPairs):
        validSubarrays = 0
        maxLeft = 0
        secondMaxLeft = 0
        gains = [0] * (n + 1)
        conflicts = [[] for _ in range(n + 1)]
        for a, b in conflictingPairs:
            conflicts[max(a, b)].append(min(a, b))
        for right in range(1, n + 1):
            for left in conflicts[right]:
                if left > maxLeft:
                    secondMaxLeft = maxLeft
                    maxLeft = left
                elif left > secondMaxLeft:
                    secondMaxLeft = left
            validSubarrays += right - maxLeft
            gains[maxLeft] += maxLeft - secondMaxLeft
        return validSubarrays + max(gains)

import pandas as pd

def analyze_organization_hierarchy(employees):
    employees = employees.copy()
    employees['level'] = None
    ceo_id = employees.loc[employees['manager_id'].isna(), 'employee_id'].values[0]
    employees.loc[employees['employee_id'] == ceo_id, 'level'] = 1

    def compute_levels(emp_df, level):
        next_level_ids = emp_df[emp_df['level'] == level]['employee_id'].tolist()
        if not next_level_ids:
            return
        emp_df.loc[emp_df['manager_id'].isin(next_level_ids), 'level'] = level + 1
        compute_levels(emp_df, level + 1)
    compute_levels(employees, 1)
    team_size = {eid: 0 for eid in employees['employee_id']}
    budget = {eid: salary for eid, salary in zip(employees['employee_id'], employees['salary'])}
    for eid in employees.sort_values('level', ascending=False)['employee_id']:
        manager_id = employees.loc[employees['employee_id'] == eid, 'manager_id'].values[0]
        if pd.notna(manager_id):
            team_size[manager_id] += team_size[eid] + 1
            budget[manager_id] += budget[eid]
    employees['team_size'] = employees['employee_id'].map(team_size)
    employees['budget'] = employees['employee_id'].map(budget)
    employees = employees.sort_values(by=['level', 'budget', 'employee_name'], ascending=[True, False, True])
    return employees[['employee_id', 'employee_name', 'level', 'team_size', 'budget']]

