class TrieNode:

    def __init__(self):
        self.children = {}
        self.count = 0

class Trie:

    def __init__(self, k):
        self.k = k
        self.root = TrieNode()
        self.prefixLengthsCount = collections.Counter()
        self.prefixLengths = SortedList()

    def insert(self, word):
        node = self.root
        for i, c in enumerate(word):
            sz = i + 1
            node = node.children.setdefault(c, TrieNode())
            node.count += 1
            if node.count >= self.k:
                self.prefixLengthsCount[sz] += 1
                if self.prefixLengthsCount[sz] == 1:
                    self.prefixLengths.add(-sz)

    def erase(self, word):
        node = self.root
        for i, c in enumerate(word):
            sz = i + 1
            node = node.children[c]
            if node.count == self.k:
                self.prefixLengthsCount[sz] -= 1
                if self.prefixLengthsCount[sz] == 0:
                    self.prefixLengths.remove(-sz)
            node.count -= 1

    def getLongestCommonPrefix(self):
        return 0 if not self.prefixLengths else -self.prefixLengths[0]

class Solution:

    def longestCommonPrefix(self, words, k):
        ans = []
        trie = Trie(k)
        for word in words:
            trie.insert(word)
        for word in words:
            trie.erase(word)
            ans.append(trie.getLongestCommonPrefix())
            trie.insert(word)
        return ans

class Solution:

    def longestSpecialPath(self, edges, nums):
        maxLength = 0
        minNodes = 1
        graph = [[] for _ in range(len(nums))]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        prefix = [0]
        lastSeenDepth = {}

        def dfs(u, prev, leftBoundary):
            nonlocal maxLength, minNodes
            prevDepth = lastSeenDepth.get(nums[u], 0)
            lastSeenDepth[nums[u]] = len(prefix)
            if prevDepth != 0:
                leftBoundary = sorted(leftBoundary + [prevDepth])[-2:]
            length = prefix[-1] - prefix[leftBoundary[0]]
            nodes = len(prefix) - leftBoundary[0]
            if length > maxLength or (length == maxLength and nodes < minNodes):
                maxLength = length
                minNodes = nodes
            for v, w in graph[u]:
                if v == prev:
                    continue
                prefix.append(prefix[-1] + w)
                dfs(v, u, leftBoundary)
                prefix.pop()
            lastSeenDepth[nums[u]] = prevDepth
        dfs(0, -1, leftBoundary=[0, 0])
        return [maxLength, minNodes]

class Solution:

    def maxSum(self, nums):
        mx = max(nums)
        if mx <= 0:
            return mx
