class Solution:

    def solveQueries(self, nums, queries):
        n = len(nums)
        minDist = [n] * n
        lastSeen = {}
        for i in range(n * 2):
            index = i % n
            num = nums[index]
            if num in lastSeen:
                prevIndex = lastSeen[num] % n
                d = i - prevIndex
                minDist[index] = min(minDist[index], d)
                minDist[prevIndex] = min(minDist[prevIndex], d)
            lastSeen[num] = i
        return [-1 if minDist[query] == n else minDist[query] for query in queries]

class Solution:

    def minZeroArray(self, nums, queries):
        if all((num == 0 for num in nums)):
            return 0
        n = len(nums)
        subsetSums = [{0} for _ in range(n)]
        for k, (l, r, val) in enumerate(queries):
            for i in range(l, r + 1):
                newSums = {subsetSum + val for subsetSum in subsetSums[i]}
                subsetSums[i].update(newSums)
            if all((nums[i] in subsetSums[i] for i in range(n))):
                return k + 1
        return -1

class Solution:

    def beautifulNumbers(self, l, r):

        @functools.lru_cache(None)
        def dp(s, i, tight, isLeadingZero, hasZero, sum, prod):
            if i == len(s):
                if isLeadingZero:
                    return 0
                return 1 if hasZero or prod % sum == 0 else 0
            if not isLeadingZero and hasZero and (not tight):
                return 10 ** (len(s) - i)
            res = 0
            maxDigit = int(s[i]) if tight else 9
            for d in range(maxDigit + 1):
                nextTight = tight and d == maxDigit
                nextIsLeadingZero = isLeadingZero and d == 0
                nextHasZero = not nextIsLeadingZero and d == 0
                nextProd = 1 if nextIsLeadingZero else prod * d
                res += dp(s, i + 1, nextTight, nextIsLeadingZero, nextHasZero, sum + d, nextProd)
            return res
        return dp(str(r), 0, tight=True, isLeadingZero=True, hasZero=False, sum=0, prod=1) - dp(str(l - 1), 0, tight=True, isLeadingZero=True, hasZero=False, sum=0, prod=1)

