class UnionFind:

    def __init__(self, n):
        self.count = n
        self.id = list(range(n))
        self.rank = [0] * n

    def unionByRank(self, u, v):
        i = self._find(u)
        j = self._find(v)
        if i == j:
            return
        if self.rank[i] < self.rank[j]:
            self.id[i] = j
        elif self.rank[i] > self.rank[j]:
            self.id[j] = i
        else:
            self.id[i] = j
            self.rank[j] += 1
        self.count -= 1

    def getCount(self):
        return self.count

    def _find(self, u):
        if self.id[u] != u:
            self.id[u] = self._find(self.id[u])
        return self.id[u]

