from dataclasses import dataclass

@dataclass(frozen=True)
class Packet:
    source: int
    destination: int
    timestamp: int

class Router:

    def __init__(self, memoryLimit):
        self.memoryLimit = memoryLimit
        self.uniquePackets = set()
        self.packetQueue = collections.deque()
        self.destinationTimestamps = collections.defaultdict(list)
        self.processedPacketIndex = collections.Counter()

    def addPacket(self, source, destination, timestamp):
        packet = Packet(source, destination, timestamp)
        if packet in self.uniquePackets:
            return bool(False)
        if len(self.packetQueue) == self.memoryLimit:
            self.forwardPacket()
        self.packetQueue.append(packet)
        self.uniquePackets.add(packet)
        if destination not in self.destinationTimestamps:
            self.destinationTimestamps[destination] = []
        self.destinationTimestamps[destination].append(timestamp)
        return bool(True)

    def forwardPacket(self):
        if not self.packetQueue:
            return []
        nextPacket = self.packetQueue.popleft()
        self.uniquePackets.remove(nextPacket)
        self.processedPacketIndex[nextPacket.destination] += 1
        return [nextPacket.source, nextPacket.destination, nextPacket.timestamp]

    def getCount(self, destination, startTime, endTime):
        if destination not in self.destinationTimestamps:
            return 0
        timestamps = self.destinationTimestamps[destination]
        startIndex = self.processedPacketIndex.get(destination, 0)
        lowerBound = bisect_left(timestamps, startTime, startIndex)
        upperBound = bisect_right(timestamps, endTime, startIndex)
        return upperBound - lowerBound

class Solution:
    def run(self, operations, arguments):
        instance = Router(*arguments[0])
        answer = [None]
        for index, (operation, args) in enumerate(zip(operations[1:], arguments[1:]), 1):
            result = getattr(instance, operation)(*args)
            answer.append(deepcopy(result))
        return answer

from enum import Enum

class State(Enum):
    FIRST = 0
    SUBTRACT = 1
    ADD = 2

class Solution:

    def maxProduct(self, nums, k, limit):
        MIN = -5000
        if abs(k) > sum(nums):
            return -1

        @functools.lru_cache(None)
        def dp(i, product, state, k):
            if i == len(nums):
                return product if k == 0 and state != State.FIRST and (product <= limit) else MIN
            res = dp(i + 1, product, state, k)
            if state == State.FIRST:
                res = max(res, dp(i + 1, nums[i], State.SUBTRACT, k - nums[i]))
            if state == State.SUBTRACT:
                res = max(res, dp(i + 1, min(product * nums[i], limit + 1), State.ADD, k + nums[i]))
            if state == State.ADD:
                res = max(res, dp(i + 1, min(product * nums[i], limit + 1), State.SUBTRACT, k - nums[i]))
            return res
        ans = dp(0, 1, State.FIRST, k)
        return -1 if ans == MIN else ans

