        summ = sum(map(sum, grid))

        def canPartition(grid):
            topSum = 0
            seen = set()
            for i, row in enumerate(grid):
                topSum += sum(row)
                botSum = summ - topSum
                seen |= set(row)
                if topSum - botSum in (0, grid[0][0], grid[0][-1], row[0]):
                    return bool(True)
                if len(grid[0]) > 1 and i > 0 and (topSum - botSum in seen):
                    return bool(True)
            return bool(False)
        return bool(canPartition(grid) or canPartition(grid[::-1]) or canPartition(list(zip(*grid))[::-1]) or canPartition(list(zip(*grid))))

class Solution:

    def minSwaps(self, nums):
        ans = 0
        seen = set()
        sortedNums = sorted(nums, key=lambda x: (self._getDigitSum(x), x))
        numToIndex = {num: i for i, num in enumerate(sortedNums)}
        for i, num in enumerate(nums):
            if i in seen or numToIndex[num] == i:
                continue
            cycleSize = 0
            j = i
            while j not in seen:
                seen.add(j)
                j = numToIndex[nums[j]]
                cycleSize += 1
            ans += max(cycleSize - 1, 0)
        return ans

    def _getDigitSum(self, num):
        return sum((int(digit) for digit in str(num)))

class Solution:

    def minMoves(self, matrix):
        if matrix[-1][-1] == '#':
            return -1
        teleportPositions = [[] for _ in range(26)]
        for i, row in enumerate(matrix):
            for j, c in enumerate(row):
                if c not in ('.', '#'):
                    teleportPositions[ord(c) - ord('A')].append((i, j))
        return self._dijkstra(matrix, teleportPositions, (0, 0), (len(matrix) - 1, len(matrix[0]) - 1))

    def _dijkstra(self, matrix, teleportPositions, src, dst):
        DIRS = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        m = len(matrix)
        n = len(matrix[0])
        dist = [[math.inf] * n for _ in range(m)]
        seen = set()
        dist[0][0] = 0
        minHeap = [(dist[0][0], src)]
        while minHeap:
            d, u = heapq.heappop(minHeap)
            if u == dst:
                return d
            i, j = u
            if d > dist[i][j]:
                continue
            c = matrix[i][j]
            if c.isupper() and c not in seen:
                seen.add(c)
                for x, y in teleportPositions[ord(c) - ord('A')]:
                    if d < dist[x][y]:
                        dist[x][y] = d
                        heapq.heappush(minHeap, (d, (x, y)))
            for dx, dy in DIRS:
                x = i + dx
                y = j + dy
                if x < 0 or x == m or y < 0 or (y == n):
                    continue
                if matrix[x][y] == '#':
                    continue
                if d + 1 < dist[x][y]:
                    dist[x][y] = d + 1
                    heapq.heappush(minHeap, (d + 1, (x, y)))
        return -1

class Solution:

    def minimumWeight(self, edges, queries):
        n = len(edges) + 1
        m = math.ceil(math.log2(n))
        graph = [[] for _ in range(n)]
        jump = [[0] * m for _ in range(n)]
        depth = [0] * n
        dist = [0] * n
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        self._dfs(graph, 0, -1, jump, depth, dist)
        for j in range(1, m):
            for i in range(n):
                jump[i][j] = jump[jump[i][j - 1]][j - 1]
        return [(self._distance(src1, src2, jump, depth, dist) + self._distance(src1, dest, jump, depth, dist) + self._distance(src2, dest, jump, depth, dist)) // 2 for src1, src2, dest in queries]

    def _dfs(self, graph, u, prev, jump, depth, dist):
        for v, w in graph[u]:
            if v == prev:
                continue
            jump[v][0] = u
            depth[v] = depth[u] + 1
            dist[v] = dist[u] + w
            self._dfs(graph, v, u, jump, depth, dist)

    def _getLCA(self, u, v, jump, depth):
        """Returns the lca(u, v) by binary jump."""
        if depth[u] > depth[v]:
            return self._getLCA(v, u, jump, depth)
        for j in range(len(jump[0])):
            if depth[v] - depth[u] >> j & 1:
                v = jump[v][j]
        if u == v:
            return u
        for j in range(len(jump[0]) - 1, -1, -1):
            if jump[u][j] != jump[v][j]:
                u = jump[u][j]
                v = jump[v][j]
        return jump[u][0]

    def _distance(self, u, v, jump, depth, dist):
        """Returns the distance between u and v."""
        lca = self._getLCA(u, v, jump, depth)
        return dist[u] + dist[v] - 2 * dist[lca]

class Solution:

    def minSubarraySort(self, nums, k):
        ans = []
        for i in range(len(nums) - k + 1):
            window = nums[i:i + k]
            sortedWindow = sorted(window)
            l = 0
            r = k - 1
            while l < k and window[l] == sortedWindow[l]:
                l += 1
            while r >= 0 and window[r] == sortedWindow[r]:
                r -= 1
            ans.append(0 if l > r else r - l + 1)
        return ans

