class Solution:

    def assignEdgeWeights(self, edges):
        MOD = 1000000007
        n = len(edges) + 1
        graph = [[] for _ in range(n + 1)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        q = collections.deque([1])
        seen = {1}
        step = 0
        while q:
            for _ in range(len(q)):
                u = q.popleft()
                for v in graph[u]:
                    if v not in seen:
                        q.append(v)
                        seen.add(v)
            step += 1
        return pow(2, step - 2, MOD) if step > 0 else 0

class Solution:

    def assignEdgeWeights(self, edges, queries):
        MOD = 1000000007
        LOG = 17
        n = len(edges) + 1
        ans = []
        depth = [0] * (n + 1)
        graph = [[] for _ in range(n + 1)]
        parent = [[-1] * (n + 1) for _ in range(LOG)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def dfs(u, p):
            parent[0][u] = p
            for v in graph[u]:
                if v != p:
                    depth[v] = depth[u] + 1
                    dfs(v, u)
        dfs(1, -1)
        for k in range(1, LOG):
            for v in range(1, n + 1):
                if parent[k - 1][v] != -1:
                    parent[k][v] = parent[k - 1][parent[k - 1][v]]

        def lca(u, v):
            if depth[u] < depth[v]:
                u, v = (v, u)
            for k in reversed(range(LOG)):
                if parent[k][u] != -1 and depth[parent[k][u]] >= depth[v]:
                    u = parent[k][u]
            if u == v:
                return u
            for k in reversed(range(LOG)):
                if parent[k][u] != -1 and parent[k][u] != parent[k][v]:
                    u = parent[k][u]
                    v = parent[k][v]
            return parent[0][u]
        for u, v in queries:
            if u == v:
                ans.append(0)
            else:
                a = lca(u, v)
                d = depth[u] + depth[v] - 2 * depth[a]
                ans.append(pow(2, d - 1, MOD))
        return ans

