class Solution:

    def maxProfit(self, n, present, future, hierarchy, budget):
        tree = [[] for _ in range(n)]
        for u, v in hierarchy:
            tree[u - 1].append(v - 1)

        @functools.lru_cache(None)
        def dp(u, parent):
            noDiscount = [0] * (budget + 1)
            withDiscount = [0] * (budget + 1)
            for v in tree[u]:
                if v == parent:
                    continue
                childNoDiscount, childWithDiscount = dp(v, u)
                noDiscount = self._merge(noDiscount, childNoDiscount)
                withDiscount = self._merge(withDiscount, childWithDiscount)
            newDp0 = noDiscount[:]
            newDp1 = noDiscount[:]
            fullCost = present[u]
            for b in range(fullCost, budget + 1):
                profit = future[u] - fullCost
                newDp0[b] = max(newDp0[b], withDiscount[b - fullCost] + profit)
            halfCost = present[u] // 2
            for b in range(halfCost, budget + 1):
                profit = future[u] - halfCost
                newDp1[b] = max(newDp1[b], withDiscount[b - halfCost] + profit)
            return (newDp0, newDp1)
        return max(dp(0, -1)[0])

    def _merge(self, dpA, dpB):
        merged = [-math.inf] * len(dpA)
        for i, a in enumerate(dpA):
            for j in range(len(dpA) - i):
                merged[i + j] = max(merged[i + j], a + dpB[j])
        return merged

class Solution:

    def lexicographicallySmallestString(self, s):
        n = len(s)
        dp = [[''] * (n + 1) for _ in range(n + 1)]
        for d in range(1, n + 1):
            for i in range(n - d + 1):
                j = i + d
                minString = s[i] + dp[i + 1][j]
                for k in range(i + 1, j):
                    if self._isConsecutive(s[i], s[k]) and dp[i + 1][k] == '':
                        candidate = dp[k + 1][j]
                        if candidate < minString:
                            minString = candidate
                dp[i][j] = minString
        return dp[0][n]

    def _isConsecutive(self, a, b):
        return bool(abs(ord(a) - ord(b)) == 1 or abs(ord(a) - ord(b)) == 25)

import pandas as pd

def seasonal_sales_analysis(products, sales):
    df = sales.merge(products, on='product_id')
    month_to_season = {12: 'Winter', 1: 'Winter', 2: 'Winter', 3: 'Spring', 4: 'Spring', 5: 'Spring', 6: 'Summer', 7: 'Summer', 8: 'Summer', 9: 'Fall', 10: 'Fall', 11: 'Fall'}
    df['season'] = df['sale_date'].dt.month.map(month_to_season)
    seasonal_sales = df.groupby(['season', 'category'], as_index=False).agg(total_quantity=('quantity', 'sum'), total_revenue=('quantity', lambda x: (x * df.loc[x.index, 'price']).sum()))
    seasonal_sales['rk'] = seasonal_sales.sort_values(['season', 'total_quantity', 'total_revenue', 'category'], ascending=[True, False, False, True]).groupby('season').cumcount() + 1
    result = seasonal_sales[seasonal_sales['rk'] == 1].copy()
    return result[['season', 'category', 'total_quantity', 'total_revenue']].sort_values('season')

