def find_books_with_no_available_copies(library_books, borrowing_records):
    current_borrowers = borrowing_records[borrowing_records['return_date'].isna()].groupby('book_id').size().rename('current_borrowers').reset_index()
    merged = library_books.merge(current_borrowers, on='book_id', how='inner')
