    def run(self, vals, par):
        children=[[] for _ in vals]
        for node in range(1,len(vals)):
            children[par[node]].append(node)
        answer=0
        def visit(node):
            nonlocal answer
            dp={0:0}
            digits=str(vals[node])
            if len(set(digits))==len(digits):
                mask=sum(1<<int(digit) for digit in digits)
                dp[mask]=vals[node]
            for child in children[node]:
                child_dp=visit(child)
                merged=dict(dp)
                for mask,score in dp.items():
                    for other,value in child_dp.items():
                        if mask&other==0:
                            merged[mask|other]=max(merged.get(mask|other,0),score+value)
                dp=merged
            answer=(answer+max(dp.values()))%1000000007
            return dp
        visit(0)
        return answer

