class BinarySumTrie:

    def __init__(self):
        self.count = 0
        self.children = [None, None]

    def add(self, num, delta, bit=17):
        self.count += delta
        if bit < 0:
            return
        b = num >> bit & 1
        if not self.children[b]:
            self.children[b] = BinarySumTrie()
        self.children[b].add(num, delta, bit - 1)

    def collect(self, prefix=0, bit=17, output=None):
        if output is None:
            output = []
        if self.count == 0:
            return output
        if bit < 0:
            output.append(prefix)
            return output
        if self.children[0]:
            self.children[0].collect(prefix, bit - 1, output)
        if self.children[1]:
            self.children[1].collect(prefix | 1 << bit, bit - 1, output)
        return output

    def exists(self, num, bit=17):
        if self.count == 0:
            return False
        if bit < 0:
            return True
        b = num >> bit & 1
        return self.children[b].exists(num, bit - 1) if self.children[b] else False

    def find_kth(self, k, bit=17):
        if k > self.count:
            return -1
        if bit < 0:
            return 0
        left_count = self.children[0].count if self.children[0] else 0
        if k <= left_count:
            return self.children[0].find_kth(k, bit - 1)
        elif self.children[1]:
            return (1 << bit) + self.children[1].find_kth(k - left_count, bit - 1)
        else:
            return -1

class Solution:

    def kthSmallest(self, par, vals, queries):
        n = len(par)
