class Solution:
    def run(self, n, k, m, time, mul):
        if k==1 and n>1:
            return -1
        if n>10:
            raise ValueError('Use at most 10 people for this visual state graph / Tối đa 10 người.')
        full=(1<<n)-1
        dist={(0,0,0):0}
        heap=[(0,0,0,0)]
        while heap:
            elapsed,mask,side,stage=heappop(heap)
            if elapsed!=dist[(mask,side,stage)]:
                continue
            if mask==full:
                return elapsed
            people=[i for i in range(n) if bool(mask>>i&1)==bool(side)]
            sizes=range(1,min(k,len(people))+1) if side==0 else [1]
            for size in sizes:
                for group in combinations(people,size):
                    duration=max(time[i] for i in group)*mul[stage]
                    next_stage=(stage+floor(duration))%m
                    next_mask=mask
                    for i in group:
                        next_mask^=1<<i
                    state=(next_mask,1-side,next_stage)
                    if elapsed+duration<dist.get(state,inf):
                        dist[state]=elapsed+duration
                        heappush(heap,(elapsed+duration,*state))
        return -1

class Solution:
    def run(self, nums):
        once=twice=0
        for value in nums:
            once=(once^value)&~twice
            twice=(twice^value)&~once
        bit=(once|twice)&-(once|twice)
        a=b=c=d=0
        for value in nums:
            if value&bit:
                a=(a^value)&~b
                b=(b^value)&~a
            else:
                c=(c^value)&~d
                d=(d^value)&~c
        return [a|c,b|d]

