    def run(self, n, edges):
        graph=[[] for _ in range(n)]
        for u,v,start,end in edges:
            graph[u].append((v,start,end))
        distance=[inf]*n
        distance[0]=0
        heap=[(0,0)]
        while heap:
            time,node=heappop(heap)
            if time!=distance[node]:
                continue
            for child,start,end in graph[node]:
                departure=max(time,start)
