    def run(self, nums, maxC):
        def feasible(length):
            changed=0
            last=-1
            for right in range(length,len(nums)):
                left=right-length
                if last>=left:
                    continue
                common=0
                for value in nums[left:right+1]:
                    common=gcd(common,value)
                if common>=2:
                    changed+=1
                    last=right
            return changed<=maxC
        left,right=0,len(nums)
        while left<right:
            mid=(left+right)//2
            if feasible(mid):
                right=mid
            else:
                left=mid+1
        return left

