        if n<5:
            return []
        if n>8:
            raise ValueError('Visual scheduling limit: 8 teams / Tối đa 8 đội.')
        matches={(a,b) for a in range(n) for b in range(n) if a!=b}
        schedule=[]
        def search(previous):
            if not matches:
                return True
            choices=[match for match in matches if not set(match)&set(previous)]
            choices.sort(key=lambda match:(sum(not set(match)&set(other) for other in matches),match))
            for match in choices:
                matches.remove(match)
                schedule.append(list(match))
                if search(match):
                    return True
                schedule.pop()
                matches.add(match)
            return False
        return schedule if search(()) else []

