class Solution:
    def minSplitMerge(self, nums1, nums2):
        start,target=tuple(nums1),tuple(nums2)
        if start==target:
            return 0
        front,back={start},{target}
        forward,backward={start:0},{target:0}
        n=len(nums1)
        while front and back:
            if len(front)>len(back):
                front,back=back,front
                forward,backward=backward,forward
            next_front=set()
            for state in front:
                for left in range(n):
                    for right in range(left+1,n+1):
                        block=state[left:right]
                        rest=state[:left]+state[right:]
                        for index in range(len(rest)+1):
                            candidate=rest[:index]+block+rest[index:]
                            if candidate in forward:
                                continue
                            moves=forward[state]+1
                            if candidate in backward:
                                return moves+backward[candidate]
                            forward[candidate]=moves
                            next_front.add(candidate)
            front=next_front
        return -1

class SparseTableRMQ:

    def __init__(self, data):
        self.n = len(data)
        self.max_log = self.n.bit_length() + 1
        self.f_max = [[0] * self.max_log for _ in range(self.n)]
        self.f_min = [[0] * self.max_log for _ in range(self.n)]
        self.lg = [0] * (self.n + 1)
        for i in range(2, self.n + 1):
            self.lg[i] = self.lg[i >> 1] + 1
        for i in range(self.n):
            self.f_max[i][0] = data[i]
            self.f_min[i][0] = data[i]
        for j in range(1, self.max_log):
            for i in range(self.n - (1 << j) + 1):
                self.f_max[i][j] = max(self.f_max[i][j - 1], self.f_max[i + (1 << j - 1)][j - 1])
                self.f_min[i][j] = min(self.f_min[i][j - 1], self.f_min[i + (1 << j - 1)][j - 1])

    def query_max(self, l, r):
        k = self.lg[r - l + 1]
        return max(self.f_max[l][k], self.f_max[r - (1 << k) + 1][k])

    def query_min(self, l, r):
        k = self.lg[r - l + 1]
        return min(self.f_min[l][k], self.f_min[r - (1 << k) + 1][k])

class Solution:

    def maxTotalValue(self, nums, k):
        n = len(nums)
        st = SparseTableRMQ(nums)
        pq = []
        for l in range(n):
            val = st.query_max(l, n - 1) - st.query_min(l, n - 1)
            heappush(pq, (-val, l, n - 1))
        ans = 0
        for _ in range(k):
            val, l, r = heappop(pq)
            ans += -val
            if r > l:
                val = st.query_max(l, r - 1) - st.query_min(l, r - 1)
                heappush(pq, (-val, l, r - 1))
        return ans

class Solution:

    def majorityFrequencyGroup(self, s):
        cnt = Counter(s)
        f = defaultdict(list)
        for c, v in cnt.items():
            f[v].append(c)
        mx = mv = 0
        ans = []
        for v, cs in f.items():
            if mx < len(cs) or (mx == len(cs) and mv < v):
                mx = len(cs)
                mv = v
                ans = cs
        return ''.join(ans)

class Solution:

    def climbStairs(self, n, costs):
        n = len(costs)
        f = [inf] * (n + 1)
        f[0] = 0
        for i, x in enumerate(costs, 1):
            for j in range(i - 3, i):
                if j >= 0:
                    f[i] = min(f[i], f[j] + x + (i - j) ** 2)
        return f[n]

class Solution:

    def distinctPoints(self, s, k):
        n = len(s)
        f = [0] * (n + 1)
        g = [0] * (n + 1)
        x = y = 0
        for i, c in enumerate(s, 1):
            if c == 'U':
                y += 1
            elif c == 'D':
                y -= 1
            elif c == 'L':
                x -= 1
            else:
                x += 1
            f[i] = x
            g[i] = y
        st = set()
        for i in range(k, n + 1):
            a = f[n] - (f[i] - f[i - k])
            b = g[n] - (g[i] - g[i - k])
            st.add((a, b))
        return len(st)

class Solution:
    def run(self, nums, swaps):
        parent=list(range(len(nums)))
        def root(node):
            while parent[node]!=node:
                node=parent[node]
            return node
        for u,v in swaps:
            parent[root(u)]=root(v)
        groups=defaultdict(list)
        for i in range(len(nums)):
            groups[root(i)].append(i)
        answer=0
        for indices in groups.values():
            values=sorted(nums[i] for i in indices)
            positive=sum(i%2==0 for i in indices)
            answer+=sum(values[-positive:]) if positive else 0
            answer-=sum(values[:len(values)-positive])
        return answer

