class Solution:

    def longestSubsequence(self, nums):
        n = len(nums)
        xor = cnt0 = 0
        for x in nums:
            xor ^= x
            cnt0 += int(x == 0)
        if xor:
            return n
        if cnt0 == n:
            return 0
        return n - 1

class Solution:

    def removeSubstring(self, s, k):
        stk = []
        for c in s:
            if stk and stk[-1][0] == c:
                stk[-1][1] += 1
            else:
                stk.append([c, 1])
            if c == ')' and len(stk) > 1 and (stk[-1][1] == k) and (stk[-2][1] >= k):
                stk.pop()
                stk[-1][1] -= k
                if stk[-1][1] == 0:
                    stk.pop()
        return ''.join((c * v for c, v in stk))

class Solution:

    def countNoZeroPairs(self, n):
        trivanople = n
        digits = list(map(int, str(trivanople)))[::-1]
        digits.append(0)
        L = len(digits)
        dp = [[[0] * 2 for _ in range(2)] for _ in range(2)]
        dp[0][1][1] = 1
        for pos in range(L):
            ndp = [[[0] * 2 for _ in range(2)] for _ in range(2)]
            target = digits[pos]
            for carry in range(2):
                for aliveA in range(2):
                    for aliveB in range(2):
                        ways = dp[carry][aliveA][aliveB]
                        if ways == 0:
                            continue
                        if aliveA:
                            A = [(d, 1) for d in range(1, 10)]
                            if pos > 0:
                                A.append((0, 0))
                        else:
                            A = [(0, 0)]
                        if aliveB:
                            B = [(d, 1) for d in range(1, 10)]
                            if pos > 0:
                                B.append((0, 0))
                        else:
                            B = [(0, 0)]
                        for da, na in A:
                            for db, nb in B:
                                s = da + db + carry
                                if s % 10 != target:
                                    continue
                                ndp[s // 10][na][nb] += ways
            dp = ndp
        return dp[0][0][0]

    def countPairs(self, n):
        return self.countNoZeroPairs(n)

