class ExamTracker:

    def __init__(self):
        self.times = [0]
        self.pre = [0]

    def record(self, time, score):
        self.times.append(time)
        self.pre.append(self.pre[-1] + score)

    def totalScore(self, startTime, endTime):
        l = bisect_left(self.times, startTime) - 1
        r = bisect_left(self.times, endTime + 1) - 1
        return self.pre[r] - self.pre[l]

class Solution:
    def run(self, operations, arguments):
        instance = ExamTracker(*arguments[0])
        answer = [None]
        for index, (operation, args) in enumerate(zip(operations[1:], arguments[1:]), 1):
            result = getattr(instance, operation)(*args)
            answer.append(deepcopy(result))
        return answer

class Solution:
    def run(self, points):
        n=len(points)
        if n==2:
            return 0
        distances=[[abs(a[0]-b[0])+abs(a[1]-b[1]) for b in points] for a in points]
        def feasible(threshold):
            colors=[-1]*n
            for start in range(n):
                if colors[start]!=-1:
                    continue
                colors[start]=0
                queue=deque([start])
                while queue:
                    node=queue.popleft()
                    for child in range(n):
                        if child==node or distances[node][child]>=threshold:
                            continue
                        if colors[child]==colors[node]:
                            return False
                        if colors[child]==-1:
                            colors[child]=1-colors[node]
                            queue.append(child)
            return True
        left,right=0,max(map(max,distances))+1
        while left+1<right:
            mid=(left+right)//2
            if feasible(mid):
                left=mid
            else:
                right=mid
        return left

