class Solution:

    def longestBalanced(self, s):

        def calc1(s):
            res = 0
            i, n = (0, len(s))
            while i < n:
                j = i + 1
                while j < n and s[j] == s[i]:
                    j += 1
                res = max(res, j - i)
                i = j
            return res

        def calc2(s, a, b):
            res = 0
            i, n = (0, len(s))
            while i < n:
                while i < n and s[i] not in (a, b):
                    i += 1
                pos = {0: i - 1}
                d = 0
                while i < n and s[i] in (a, b):
                    d += 1 if s[i] == a else -1
                    if d in pos:
                        res = max(res, i - pos[d])
                    else:
                        pos[d] = i
                    i += 1
            return res

        def calc3(s):
            pos = {(0, 0): -1}
            cnt = Counter()
            res = 0
            for i, c in enumerate(s):
                cnt[c] += 1
                k = (cnt['a'] - cnt['b'], cnt['b'] - cnt['c'])
                if k in pos:
                    res = max(res, i - pos[k])
                else:
                    pos[k] = i
            return res
        x = calc1(s)
        y = max(calc2(s, 'a', 'b'), calc2(s, 'b', 'c'), calc2(s, 'a', 'c'))
        z = calc3(s)
        return max(x, y, z)

class Solution:
    def run(self, n, edges, nums):
        graph=[[] for _ in range(n)]
        for u,v in edges:
            graph[u].append(v)
            graph[v].append(u)
        answer=0
        def visit(node,parent,ancestors):
            nonlocal answer
            for value in ancestors:
                product=value*nums[node]
                answer+=isqrt(product)**2==product
            for child in graph[node]:
                if child!=parent:
                    visit(child,node,ancestors+[nums[node]])
        visit(0,-1,[])
        return answer

class Solution:

    def minOperations(self, nums):
        f = {nums[0]: 0}
        for x in nums[1:]:
            g = {}
            for pre, s in f.items():
                cur = (x + pre - 1) // pre * pre
                while cur <= 100:
                    if cur not in g or g[cur] > s + cur - x:
                        g[cur] = s + cur - x
                    cur += pre
            f = g
        return min(f.values())

class Solution:

    def longestBalanced(self, nums):
        n = len(nums)
