        for i in range(n):
            cnt = [0, 0]
            vis = set()
            for j in range(i, n):
                if nums[j] not in vis:
                    cnt[nums[j] & 1] += 1
                    vis.add(nums[j])
                if cnt[0] == cnt[1]:
                    ans = max(ans, j - i + 1)
        return ans

class Solution:

    def longestBalanced(self, nums):
        n = len(nums)

        class Node:
            __slots__ = ('l', 'r', 'mn', 'mx', 'lazy')

            def __init__(self):
                self.l = self.r = 0
                self.mn = self.mx = 0
                self.lazy = 0
        tr = [Node() for _ in range((n + 1) * 4)]

        def build(u, l, r):
            tr[u].l, tr[u].r = (l, r)
            tr[u].mn = tr[u].mx = tr[u].lazy = 0
            if l == r:
                return
            mid = l + r >> 1
            build(u << 1, l, mid)
            build(u << 1 | 1, mid + 1, r)

        def apply(u, v):
            tr[u].mn += v
            tr[u].mx += v
            tr[u].lazy += v

        def pushdown(u):
            if tr[u].lazy:
                apply(u << 1, tr[u].lazy)
                apply(u << 1 | 1, tr[u].lazy)
                tr[u].lazy = 0

        def pushup(u):
            tr[u].mn = min(tr[u << 1].mn, tr[u << 1 | 1].mn)
            tr[u].mx = max(tr[u << 1].mx, tr[u << 1 | 1].mx)

        def modify(u, l, r, v):
            if tr[u].l >= l and tr[u].r <= r:
                apply(u, v)
                return
            pushdown(u)
            mid = tr[u].l + tr[u].r >> 1
            if l <= mid:
                modify(u << 1, l, r, v)
            if r > mid:
                modify(u << 1 | 1, l, r, v)
            pushup(u)

        def query(u, target):
            if tr[u].l == tr[u].r:
                return tr[u].l
            pushdown(u)
            if tr[u << 1].mn <= target <= tr[u << 1].mx:
                return query(u << 1, target)
            return query(u << 1 | 1, target)
        build(1, 0, n)
        last = {}
        now = ans = 0
        for i, x in enumerate(nums, start=1):
            det = 1 if x & 1 else -1
            if x in last:
                modify(1, last[x], n, -det)
                now -= det
            last[x] = i
            modify(1, i, n, det)
            now += det
            pos = query(1, now)
            ans = max(ans, i - pos)
        return ans

class Solution:

    def lexSmallest(self, s):
        ans = s
        for k in range(1, len(s) + 1):
            t1 = s[:k][::-1] + s[k:]
            t2 = s[:-k] + s[-k:][::-1]
            ans = min(ans, t1, t2)
        return ans

class Solution:

    def maxSumOfSquares(self, num, sum):
        if num * 9 < sum:
            return ''
        k, s = divmod(sum, 9)
        ans = '9' * k
        if s:
            ans += str(s)
        ans += '0' * (num - len(ans))
        return ans

class Solution:

    def minOperations(self, nums1, nums2):
        ans = 1
        ok = False
        d = inf
        for x, y in zip(nums1, nums2):
            if x < y:
                x, y = (y, x)
            ans += x - y
            d = min(d, abs(x - nums2[-1]), abs(y - nums2[-1]))
            ok = ok or y <= nums2[-1] <= x
        if not ok:
            ans += d
        return ans

class Solution:
    def run(self, mat):
        dp={0:1}
        for row in mat:
            next_dp=defaultdict(int)
            for value in row:
                for common,count in dp.items():
                    next_dp[gcd(common,value)]=(next_dp[gcd(common,value)]+count)%1000000007
            dp=dict(next_dp)
        return dp.get(1,0)

class Solution:

    def removeZeros(self, n):
        k = 1
        ans = 0
        while n:
            x = n % 10
            if x:
                ans = k * x + ans
                k *= 10
            n //= 10
        return ans

class Solution:

    def maxAlternatingSum(self, nums):
        nums = [x * x for x in nums]
        nums.sort()
        ans, m = (0, len(nums) >> 1)
        for i, x in enumerate(nums):
            ans += -x if i < m else x
        return ans

class Solution:

    def numGoodSubarrays(self, nums, k):
        cnt = Counter({0: 1})
        ans = s = 0
        for x in nums:
            s = (s + x) % k
            ans += cnt[s]
            cnt[s] += 1
        n = len(nums)
        i = 0
        while i < n:
            j = i + 1
            while j < n and nums[j] == nums[i]:
                j += 1
            m = j - i
            for h in range(1, m + 1):
                if h * nums[i] % k == 0:
                    ans -= m - h
            i = j
        return ans

class Solution:

    def maxProduct(self, nums):
        nums.sort()
        a, b = (nums[0], nums[1])
        c, d = (nums[-2], nums[-1])
        x = 10 ** 5
        return max(a * b * x, c * d * x, a * d * -x)

class Solution:
    def run(self, d, r):
        left,right=0,1
        def feasible(time):
            return time-time//r[0]>=d[0] and time-time//r[1]>=d[1] and time-time//lcm(*r)>=sum(d)
        while not feasible(right):
            right*=2
        while left<right:
            mid=(left+right)//2
            if feasible(mid):
                right=mid
            else:
                left=mid+1
        return left

