    def run(self, nums, k):
        n=len(nums)
        prefix=[0]+list(accumulate(nums))
        dp=[inf]*(n+1)
        dp[0]=0
        for groups in range(1,k+1):
            next_dp=[inf]*(n+1)
            for right in range(groups,n+1):
                for left in range(groups-1,right):
