    def run(self, n, edges):
        parent=list(range(n))
        parity=[0]*n
        def find(node):
            value=0
            while node!=parent[node]:
                value^=parity[node]
                node=parent[node]
            return node,value
        answer=0
        for u,v,weight in edges:
            a,x=find(u)
            b,y=find(v)
            if a==b:
                if x^y==weight:
                    answer+=1
            else:
                parent[a]=b
                parity[a]=x^y^weight
                answer+=1
        return answer

class Solution:

    def minOperations(self, grid, k):
        m, n = (len(grid), len(grid[0]))
        mx = max((max(row) for row in grid))

        def check(target):
            diff = [[0] * (n + 2) for _ in range(m + 2)]
            total_ops = 0
            for i, row in enumerate(grid, 1):
                for j, val in enumerate(row, 1):
                    diff[i][j] += diff[i - 1][j] + diff[i][j - 1] - diff[i - 1][j - 1]
                    cur_val = val + diff[i][j]
                    if cur_val > target:
                        return -1
                    if cur_val < target:
                        if i + k - 1 > m or j + k - 1 > n:
                            return -1
                        needed = target - cur_val
                        total_ops += needed
                        diff[i][j] += needed
                        diff[i + k][j] -= needed
                        diff[i][j + k] -= needed
                        diff[i + k][j + k] += needed
            return total_ops
        for t in range(mx, mx + 2):
            res = check(t)
            if res != -1:
                return res
        return -1

