    def run(self, nums, k):
        n=len(nums)
        if k==0:
            return 0
        if n<2 or k>n//2:
            return -1
        cost=[max(0,max(nums[(i-1)%n],nums[(i+1)%n])+1-nums[i]) for i in range(n)]
        answer=inf
        for first in (0,1):
            dp={(first,first):cost[0]*first}
            for i in range(1,n):
                next_dp={}
                for (count,last),value in dp.items():
                    for selected in (0,1):
                        if selected and (last or i==n-1 and first):
                            continue
                        state=(count+selected,selected)
                        next_dp[state]=min(next_dp.get(state,inf),value+selected*cost[i])
                dp=next_dp
            answer=min(answer,min((value for (count,last),value in dp.items() if count>=k),default=inf))
        return answer if answer<inf else -1

