class Solution:
    def run(self, n, edges, source, target, k):
        graph=[[] for _ in range(n)]
        for u,v,weight in edges:
            graph[u].append((v,weight))
            graph[v].append((u,weight))
        def feasible(threshold):
            distance=[inf]*n
            distance[source]=0
            queue=deque([source])
            while queue:
                node=queue.popleft()
                for child,weight in graph[node]:
                    heavy=int(weight>threshold)
                    if distance[node]+heavy<distance[child]:
                        distance[child]=distance[node]+heavy
                        if heavy:
                            queue.append(child)
                        else:
                            queue.appendleft(child)
            return distance[target]<=k
        left,right=0,max((edge[2] for edge in edges),default=0)
        if not feasible(right):
            return -1
        while left<right:
            mid=(left+right)//2
            if feasible(mid):
                right=mid
            else:
                left=mid+1
        return left

