        for groups in range(1,k+1):
            next_dp=[inf]*(n+1)
            for right in range(groups,n+1):
                for left in range(groups-1,right):
                    total=prefix[right]-prefix[left]
                    next_dp[right]=min(next_dp[right],dp[left]+total*(total+1)//2)
            dp=next_dp
        return dp[n]

