        m,n=len(grid),len(grid[0])
        if m+n>10:
            raise ValueError('Visual path enumeration: rows + columns <= 10 / Tổng hàng+cột tối đa 10.')
        def paths(r,c,direction,path):
            path=path+[(r,c)]
            if c==n-1 and r==(m-1 if direction==1 else 0):
                yield frozenset(path)
            else:
                if c+1<n:
                    yield from paths(r,c+1,direction,path)
                if 0<=r+direction<m:
                    yield from paths(r+direction,c,direction,path)
        first=list(paths(0,0,1,[]))
        second=list(paths(m-1,0,-1,[]))
        answer=-inf
        for a in first:
            for b in second:
                shared=a&b
                score=sum(grid[r][c] for r,c in shared)
                answer=max(answer,score)
        return answer

class Solution:
    def run(self, parent, nums, k):
        children=[[] for _ in nums]
        for node in range(1,len(nums)):
            children[parent[node]].append(node)
        def visit(node):
            skip=[0]*k
            take=[0]*k
            skip[0]=1
            take[nums[node]%k]=1
            for child in children[node]:
                child_skip,child_take=visit(child)
                next_skip=[0]*k
                next_take=[0]*k
                for a in range(k):
                    for b in range(k):
                        next_skip[(a+b)%k]=(next_skip[(a+b)%k]+skip[a]*(child_skip[b]+child_take[b]))%1000000007
                        next_take[(a+b)%k]=(next_take[(a+b)%k]+take[a]*child_skip[b])%1000000007
                skip,take=next_skip,next_take
            return skip,take
        skip,take=visit(0)
        return (skip[0]+take[0]-1)%1000000007

