class Solution:
    def maximumSaleItems(self, items, budget):
        m = 1500
        cnt = [0] * (m + 1)
        gain = [0] * (m + 1)
        mn = min(p for f, p in items)

        for f, p in items:
            cnt[f] += 1

        for f in range(1, m + 1):
            gain[f] = sum(cnt[j] for j in range(f, m + 1, f))

        dp = [b // mn for b in range(budget + 1)]

        for f, p in items:
            g = gain[f]
            for b in range(budget, p - 1, -1):
                dp[b] = max(dp[b], dp[b - p] + g)

        return dp[budget]

