        n=len(nums)
        if n>12:
            raise ValueError('Visual subset limit: 12 vertices / Tối đa 12 đỉnh.')
        graph=[[] for _ in range(n)]
        for u,v in edges:
            graph[u].append(v)
            graph[v].append(u)
        ancestors=[0]*n
        def root_tree(node,parent,mask):
            ancestors[node]=mask|1<<node
            for child in graph[node]:
                if child!=parent:
                    root_tree(child,node,ancestors[node])
        root_tree(0,-1,0)
        conflicts=[]
        for start in range(n):
            queue=deque([(start,-1,0)])
            while queue:
                node,parent,distance=queue.popleft()
                if start<node and distance<k:
                    conflicts.append((1<<start)|(1<<node))
                for child in graph[node]:
                    if child!=parent:
                        queue.append((child,node,distance+1))
        answer=-inf
        for selected in range(1<<n):
            if any(selected&pair==pair for pair in conflicts):
                continue
            score=sum(-value if (selected&ancestors[i]).bit_count()%2 else value for i,value in enumerate(nums))
            answer=max(answer,score)
        return answer

