class Solution:
    def run(self, nums, s):
        dp={False:0}
        for i,char in enumerate(s):
            next_dp={}
            for previous,score in dp.items():
                for move in ([False,True] if i>0 and char=='1' else [False]):
                    covered=previous or move
                    value=score+(nums[i-1] if i and covered else 0)
                    stay=char=='1' and not move
                    next_dp[stay]=max(next_dp.get(stay,-inf),value)
            dp=next_dp
        return max(score+(nums[-1] if last else 0) for last,score in dp.items())

class Solution:
    def run(self, nums, maxVal):
        answer=-inf
        candidates=sorted(set(nums)|set(range(max(1,maxVal-len(nums)-1),maxVal+1)),reverse=True)
        for candidate in candidates:
            if candidate<=answer:
                break
            bad=sum(gcd(value,candidate)>1 for value in nums)
            cost=min(bad-int(gcd(value,candidate)>1)+int(value!=candidate) for value in nums)
            answer=max(answer,candidate-cost)
        return answer

