class Solution:
    def run(self, nums, k):
        answer=-inf
        for left in range(len(nums)):
            for right in range(left,len(nums)):
                inside=sorted(nums[left:right+1])
                outside=sorted(nums[:left]+nums[right+1:],reverse=True)
                score=sum(inside)
                for i in range(min(k,len(inside),len(outside))):
                    if outside[i]<=inside[i]:
                        break
                    score+=outside[i]-inside[i]
                answer=max(answer,score)
        return answer

class Solution:

    def minLights(self, lights):
        n = len(lights)
        d = [0] * n
        for i, v in enumerate(lights):
            if v > 0:
                l = max(0, i - v)
                r = min(n - 1, i + v)
                d[l] += 1
                if r + 1 < n:
                    d[r + 1] -= 1
        s = cnt = 0
        ans = 0
        for x in d:
            s += x
            if s == 0:
                cnt += 1
            else:
                ans += (cnt + 2) // 3
                cnt = 0
        ans += (cnt + 2) // 3
        return ans

class Solution:

    def finishTime(self, n, edges, baseTime):

        def dfs(i):
            if not g[i]:
                return baseTime[i]
            earliest, latest = (inf, -inf)
            for j in g[i]:
                a = dfs(j)
                earliest = min(earliest, a)
                latest = max(latest, a)
            own_duration = latest - earliest + baseTime[i]
            return latest + own_duration
        g = [[] for _ in range(n)]
        for u, v in edges:
            g[u].append(v)
        return dfs(0)

class Solution:
    def run(self, l, r, k):
        def count(bound):
            if bound<0:
                return 0
            digits=list(map(int,str(bound)))
            @cache
            def dp(index,previous,tight):
                if index==len(digits):
                    return 1
                limit=digits[index] if tight else 9
                total=0
                for digit in range(limit+1):
                    if previous==-1 or abs(previous-digit)<=k:
                        new=-1 if previous==-1 and digit==0 else digit
                        total+=dp(index+1,new,tight and digit==limit)
                return total
            return dp(0,-1,True)
        return count(r)-count(l-1)

class Solution:
    def run(self, n, edges, baseTime):
        graph=[[] for _ in range(n)]
        for u,v in edges:
            graph[u].append(v)
            graph[v].append(u)
        @cache
        def finish(node,parent):
            times=[finish(child,node) for child in graph[node] if child!=parent]
            if not times:
                return baseTime[node]
            earliest,latest=min(times),max(times)
            return latest+(latest-earliest)+baseTime[node]
        return min(finish(root,-1) for root in range(n))

