class Solution:

    def shortestPath(self, n, edges, labels, k):
        g = [[] for _ in range(n)]
        for u, v, w in edges:
            g[u].append((v, w))
        dist = [[inf] * (k + 1) for _ in range(n)]
        dist[0][1] = 0
        pq = [(0, 0, 1)]
        while pq:
            d, u, cur = heappop(pq)
            if u == n - 1:
                return d
            if d > dist[u][cur]:
                continue
            for v, w in g[u]:
                nxt = 1 if labels[v] != labels[u] else cur + 1
                nd = d + w
                if nxt <= k and nd < dist[v][nxt]:
                    dist[v][nxt] = nd
                    heappush(pq, (nd, v, nxt))
        return -1

class Solution:
    def run(self, value, decay, m):
        def count_above(threshold):
            return sum(max(0,(v-threshold+d-1)//d) for v,d in zip(value,decay))
        left,right=0,max(value)
        while left<right:
            mid=(left+right)//2
            if count_above(mid)>m:
                left=mid+1
            else:
                right=mid
        threshold=left
        answer=used=0
        for v,d in zip(value,decay):
            count=max(0,(v-threshold+d-1)//d)
            answer+=count*v-d*count*(count-1)//2
            used+=count
        answer+=(m-used)*threshold
        return answer%1000000007

