class Solution:
    def run(self, n, parent, gates, queries):
        def reach(node,card,ancestor):
            counts=[int(card==0),int(card==1)]
            while node!=ancestor:
                red,blue,white=gates[node]
                counts=[(counts[0]*blue+counts[1]*white)%1000000007,(counts[1]*red+counts[0]*white)%1000000007]
                node=parent[node]
            return sum(counts)%1000000007
        answer=0
        for a,ac,b,bc in queries:
            ancestors=set()
            node=a
            while node!=-1:
                ancestors.add(node)
                node=parent[node]
            ancestor=b
            while ancestor not in ancestors:
                ancestor=parent[ancestor]
            ways=reach(a,ac,ancestor)*reach(b,bc,ancestor)%1000000007
            answer^=ways
        return answer

