            answer=0
            for i in range(a,len(word1)):
                if word1[i]==target[index]:
                    answer+=count(index+1,i+1,b,used|1)
            for j in range(b,len(word2)):
                if word2[j]==target[index]:
                    answer+=count(index+1,a,j+1,used|2)
            return answer%1000000007
        return count(0,0,0,0)

class Solution:

