class Solution:
    def run(self, nums):
        candidates={2}
        for value in nums:
            number=value
            divisor=2
            while divisor*divisor<=number:
                if number%divisor==0:
                    candidates.add(divisor)
                    while number%divisor==0:
                        number//=divisor
                divisor+=1
            if number>1:
                candidates.add(number)
        best=-inf
        chosen=2
        for k in sorted(candidates):
            current=-inf
            score=-inf
            for value in nums:
                signed=value if value%k==0 else -value
                current=max(signed,current+signed)
                score=max(score,current)
            if score>best:
                best,chosen=score,k
        return best*chosen%1000000007

