class Solution:
    def run(self, m, n, k):
        if k==1:
            height,width=1,1
            motif={(0,0)}
        elif k==2 and m>=2 and n>=2:
            height,width=2,2
            motif=set(product(range(2),repeat=2))
        elif k==3 and m>=2 and n>=3:
            height,width=2,3
            motif=set(product(range(2),range(3)))
        elif k==3 and m>=3 and n>=2:
            height,width=3,2
            motif=set(product(range(3),range(2)))
        elif k==4 and m>=2 and n>=4:
            height,width=2,4
            motif=set(product(range(2),range(4)))
        elif k==4 and m>=4 and n>=2:
            height,width=4,2
            motif=set(product(range(4),range(2)))
        elif k==4 and m>=3 and n>=3:
            height,width=3,3
            motif={(0,0),(0,1),(1,0),(1,1),(1,2),(2,1),(2,2)}
        else:
            return []
        grid=[['#']*n for _ in range(m)]
        for r,c in motif:
            grid[r][c]='.'
        for c in range(width-1,n):
            grid[height-1][c]='.'
        for r in range(height-1,m):
            grid[r][n-1]='.'
        return [''.join(row) for row in grid]

