class Solution:
    def run(self, k):
        bits=bin(k)[3:]
        height=2+2*len(bits)
        width=4+len(bits)
        grid=[['#']*width for _ in range(height)]
        for c in range(4):
            grid[0][c]='.'
        grid[1][0]=grid[1][3]='.'
        r,c=1,3
        for bit in bits:
            grid[r][c+1]='.'
            for column in (c-3,c-2,c,c+1):
                grid[r+1][column]='.'
            if bit=='1':
                grid[r+1][c-1]='.'
            grid[r+2][c-2]=grid[r+2][c+1]='.'
            r+=2
            c+=1
        return [''.join(row) for row in grid]

class Solution:

    def sortArray(self, nums, pre):
        n = len(nums)
        target = tuple(range(n))
        start = tuple(nums)
        if start == target:
            return 0
        vis = {start}
        q = deque([(start, 0)])
        while q:
            state, dist = q.popleft()
            nd = dist + 1
            for x in pre:
                nxt = state[:x][::-1] + state[x:]
                if nxt == target:
                    return nd
                if nxt not in vis:
                    vis.add(nxt)
                    q.append((nxt, nd))
        return -1

