class Solution:
    def run(self, source, target, rules, costs):
        n=len(source)
        dp=[inf]*(n+1)
        dp[0]=0
        for i in range(n):
            if source[i]==target[i]:
                dp[i+1]=min(dp[i+1],dp[i])
            for (pattern,replacement),cost in zip(rules,costs):
                end=i+len(pattern)
                if end<=n and target[i:end]==replacement and all(a=='*' or a==b for a,b in zip(pattern,source[i:end])):
