        def dfs(node):
            if node is None:
                return -inf
            l = dfs(node.left)
            r = dfs(node.right)
            mx = max(l, r, node.val)
            if mx == node.val:
                nonlocal ans
                ans += 1
            return mx
        ans = 0
        dfs(root)
        return ans

class Solution:
    def canTransform(self, s, strs):
        zeroes = s.count('0')
        answer = []
        for query_index, pattern in enumerate(strs):
            need = zeroes - pattern.count('0')
            if need < 0 or need > pattern.count('?'):
                answer.append(False)
                continue
            target = []
            for index, char in enumerate(pattern):
                if char == '?':
                    char = '0' if need > 0 else '1'
                    need -= int(char == '0')
                target.append(char)
            source_zeroes = 0
            target_zeroes = 0
            possible = True
            for index, (before, after) in enumerate(zip(s, target)):
                source_zeroes += int(before == '0')
                target_zeroes += int(after == '0')
                if target_zeroes < source_zeroes:
                    possible = False
                    break
            current = list(s)
            moves = []
            if possible:
                for index, char in enumerate(target):
                    if char == '0' and current[index] == '1':
                        zero_index = current.index('0', index + 1)
                        current[index], current[zero_index] = current[zero_index], current[index]
                        moves.append([index, zero_index])
            answer.append(possible)
        return answer

class Solution:
    def minGroups(self, words):
        groups = {}
        for index, word in enumerate(words):
            even = word[::2]
            odd = word[1::2]
            key = []
            for parity, text in enumerate((even, odd)):
                best = text
                for offset in range(len(text)):
                    candidate = text[offset:] + text[:offset]
                    if candidate < best:
                        best = candidate
                key.append(best)
            signature = tuple(key)
            if signature not in groups:
                groups[signature] = []
            groups[signature].append(word)
        return len(groups)
